window.OSCE_DATA={"nome":"OSCE IV","sub":"Estações clínicas em blocos · adulto e pediatria","estacoes":[{"id":"drge","area":"Adulto","tema":"DRGE e dispepsia","titulo":"Pirose depois de comer","caso":"Homem, 45 anos, obeso e tabagista, com pirose pós-prandial e regurgitação amarga há 3 meses. Piora com alimentos gordurosos, refrigerante e álcool; alívio parcial com antiácido. O examinador pede: verbalize a principal hipótese e, se julgar necessário, solicite exames.","blocos":[{"t":"Abertura e anamnese","q":"O que você faz e pergunta antes de concluir?","r":["Apresentar-se; confirmar nome, idade e data de nascimento.","Confirmar a queixa principal.","Perguntar outros sintomas, frequência, fatores de melhora e de piora (sinais de alarme: disfagia, perda de peso, vômitos, sangramento)."],"e":"Toda estação começa igual: apresentação, identificação do paciente e queixa. Perguntar sinais de alarme define se já vai para endoscopia."},{"t":"Hipótese e exame","q":"Qual a hipótese diagnóstica e qual exame você solicita?","r":["Hipótese: doença do refluxo gastroesofágico (DRGE).","Exame: endoscopia digestiva alta (EDA) — paciente com 45 anos."],"e":"Pirose + regurgitação, com piora após gordura/álcool e alívio com antiácido, é clínica clássica de DRGE. A idade (≥ 45 anos) justifica EDA para avaliar esofagite e Barrett."},{"t":"Orientação e alta","q":"Que orientações você dá antes de liberar o paciente?","r":["Mudança de hábitos: alimentação, exercício físico e abandono do tabagismo.","Perda de peso (obesidade).","Liberar o paciente."],"e":"Tabagismo, obesidade, álcool e refeições gordurosas reduzem a pressão do esfíncter esofágico inferior. A mudança de estilo de vida é a base do tratamento."}]},{"id":"hda","area":"Adulto","tema":"Hemorragias digestivas","titulo":"Vômitos e sangue após beber","caso":"J.C.B., 35 anos, teve vômitos intensos após ingesta excessiva de álcool e hemorragia digestiva alta. A EDA mostrou lacerações de mucosa e submucosa próximas à junção esofagogástrica. Nega etilismo crônico.","blocos":[{"t":"Anamnese","q":"O que você pergunta ao paciente?","r":["Apresentar-se; confirmar nome, idade e data de nascimento.","Confirmar a queixa principal.","Outros sintomas, frequência, fatores de melhora e de piora."],"e":"Nega etilismo crônico: isso afasta, em princípio, varizes esofágicas por hepatopatia."},{"t":"Análise da EDA","img":{"s":"data:image/jpeg;base64,","c":"Endoscopia digestiva alta — junção esofagogástrica (seta)"},"q":"Analise o exame e verbalize a hipótese diagnóstica.","r":["Laceração longitudinal de mucosa perto da junção esofagogástrica.","Síndrome de Mallory-Weiss."],"e":"Vômitos repetidos elevam a pressão intragástrica e rompem a mucosa na junção esofagogástrica. Costuma ser autolimitada. O dado-chave do enunciado: vômitos intensos antes do sangramento, sem hepatopatia prévia."}]},{"id":"abd-perf","area":"Adulto","tema":"Abdome agudo","titulo":"Dor abdominal súbita e abdome rígido","caso":"Homem, 30 anos, dor abdominal intensa de instalação súbita. Sudorese, taquicardia e abdome rígido. Fez radiografia de tórax. Realize a percussão abdominal e verbalize o sinal semiológico, o achado do Rx e o tipo de abdome agudo.","blocos":[{"t":"Anamnese","q":"O que você pergunta?","r":["Apresentar-se; confirmar nome, idade e data de nascimento.","Queixa principal.","Outros sintomas, frequência, fatores de melhora e de piora, irradiação."],"e":"Início súbito sugere perfuração ou ruptura. Pergunte antecedentes de úlcera e uso de anti-inflamatórios."},{"t":"Radiografia","img":{"s":"data:image/jpeg;base64,","c":"Radiografia de tórax em ortostatismo"},"q":"O que você observa no Rx?","r":["Ar livre sob as cúpulas diafragmáticas.","Achado radiológico: pneumoperitônio."],"e":"O ar sai da víscera perfurada e sobe para debaixo do diafragma com o paciente em pé. É o achado radiológico característico da perfuração de víscera oca."},{"t":"Percussão e diagnóstico","q":"Faça a percussão (higienize as mãos e peça permissão) e verbalize o sinal e o tipo de abdome agudo.","r":["Sinal de Jobert: timpanismo à percussão da região hepática (perda da macicez).","Pneumoperitônio ao Rx.","Tipo: abdome agudo perfurativo."],"e":"O fígado normalmente é maciço à percussão. Com ar livre na cavidade, o gás se interpõe e o som fica timpânico. Abdome rígido + sudorese + taquicardia = peritonite química/séptica, urgência cirúrgica."}]},{"id":"abd-infl","area":"Adulto","tema":"Abdome agudo","titulo":"Dor que migrou para a fossa ilíaca direita","caso":"Mulher, 35 anos, dor abdominal há 5 dias, iniciada no epigástrio e agora na fossa ilíaca direita, com inapetência e febre. Nega corrimento vaginal. Realize as manobras de Blumberg e Rovsing, verbalize a hipótese e solicite exames.","blocos":[{"t":"Anamnese dirigida","q":"Além da dor, o que você pergunta a uma mulher dessa idade?","r":["Apresentar-se; identificação; queixa principal.","Outros sintomas, melhora e piora.","Ciclo menstrual e método contraceptivo."],"e":"Em mulher em idade fértil, dor em fossa ilíaca direita exige descartar gestação ectópica, cisto/torção de ovário e DIP — por isso ciclo menstrual, contracepção e corrimento."},{"t":"Manobras","img":{"s":"data:image/jpeg;base64,","c":"Dor migratória do epigástrio para a fossa ilíaca direita"},"q":"Realize e descreva Blumberg e Rovsing.","r":["Higienizar as mãos e pedir permissão.","Blumberg: dor à descompressão brusca no ponto de McBurney.","Rovsing: pressão na fossa ilíaca esquerda empurrando o ar em direção ao ceco provoca dor na fossa ilíaca direita."],"e":"McBurney fica na união do terço externo com os dois terços internos da linha entre a espinha ilíaca ântero-superior e a cicatriz umbilical. Blumberg indica irritação peritoneal local."},{"t":"Outros sinais de apoio","img":{"s":"data:image/jpeg;base64,","c":"Pesquisa do sinal do psoas"},"q":"Que outros sinais sugerem irritação peritoneal no apêndice?","r":["Psoas: dor na extensão forçada da coxa direita (decúbito lateral esquerdo).","Obturador: dor no hipogástrio na rotação interna do quadril fletido.","Lapinsky: dor ao elevar a perna estendida com pressão profunda na fossa ilíaca direita."],"e":"O apêndice inflamado irrita o psoas ou o obturador internos, conforme sua posição (retrocecal ou pélvico)."},{"t":"Hipótese e exames","q":"Qual a hipótese e quais exames você solicita?","r":["Hipótese: apendicite aguda (abdome agudo inflamatório).","Solicitar USG e TC de abdome."],"e":"A história migratória (epigástrio → fossa ilíaca direita) com anorexia e febre, mais Blumberg e Rovsing, sustenta apendicite. Em mulher, a USG ajuda a excluir causa ginecológica."}]},{"id":"abd-obs","area":"Adulto","tema":"Abdome agudo","titulo":"Distensão, vômitos e sem evacuar há 4 dias","caso":"Homem, 49 anos, dor abdominal difusa em cólica há 2 dias, com distensão, vômitos e última evacuação há 4 dias. Laparotomia por trauma há 13 anos. Realize o exame físico abdominal total e verbalize os achados e o tipo de abdome agudo.","blocos":[{"t":"Anamnese","q":"O que você pergunta?","r":["Apresentar-se; identificação; queixa principal.","Outros sintomas, frequência, melhora e piora, irradiação.","Já dado: nega alteração prévia do hábito intestinal e perda de peso; cirurgia prévia."],"e":"Cirurgia abdominal prévia é a causa mais comum de obstrução do delgado (bridas/aderências). Ausência de emagrecimento e de mudança de hábito afasta tumor."},{"t":"Exame físico","q":"Quais os passos e os achados em cada etapa do exame?","r":["Higienizar as mãos e pedir permissão.","Inspeção: cicatriz abdominal e abdome distendido.","Ausculta: ruídos hidroaéreos aumentados.","Palpação: doloroso à palpação profunda, sem irritação peritoneal.","Percussão: timpanismo."],"e":"A ordem do exame abdominal é inspeção, ausculta, percussão e palpação (a ausculta antes de palpar evita alterar os ruídos). Sem sinais de peritonite, não há perfuração."},{"t":"Diagnóstico","q":"Qual o tipo de abdome agudo?","r":["Abdome agudo obstrutivo."],"e":"Cólica + distensão + vômitos + parada de eliminação de fezes e gases + RHA aumentados compõem a síndrome obstrutiva."}]},{"id":"litiase","area":"Adulto","tema":"Urolitíase e rins","titulo":"Cólica lombar com irradiação","caso":"Paciente de 43 anos, há 1 dia com cólica lombar esquerda intensa irradiando para a fossa ilíaca direita, náuseas e vômitos. Há 12 h, febre e queda do estado geral. Leucograma 18.000 com desvio à esquerda, PCR elevada e tomografia de abdome e pelve. Realize Giordano e, com a resposta e a TC, verbalize a hipótese.","blocos":[{"t":"Anamnese","q":"O que você pergunta?","r":["Apresentar-se; identificação; queixa principal.","Outros sintomas, melhora e piora, irradiação."],"e":"Cólica com irradiação para fossa ilíaca/genitália é típica de litíase ureteral. Febre muda a gravidade do quadro."},{"t":"Giordano","q":"Realize a manobra. Como você descreve e o que considera positivo?","r":["Higienizar as mãos e pedir permissão.","Punho-percussão da loja renal em ambos os rins.","Positivo: dor à punho-percussão da loja renal direita."],"e":"Giordano positivo indica comprometimento do rim ou da pelve renal (pielonefrite, obstrução)."},{"t":"Tomografia","img":{"s":"data:image/jpeg;base64,","c":"Tomografia de abdome e pelve"},"q":"Analise a TC e verbalize a hipótese diagnóstica.","r":["Cálculo no ureter.","Hipótese: litíase ureteral."],"e":"Cólica + febre + leucocitose é a associação perigosa: obstrução infectada exige descompressão urgente (cateter duplo J ou nefrostomia) além de antibiótico."}]},{"id":"palp-renal","area":"Adulto","tema":"Urolitíase e rins","titulo":"Dor lombar, disúria, febre e urina escura","caso":"Mulher, 24 anos, há 2 dias com dor lombar direita intermitente, náuseas e vômitos. Há 1 dia, urina escura, disúria, polaciúria, febre, mal-estar e perda do apetite. REG, 39 °C. Realize as manobras de Israel e Goelet e verbalize a hipótese.","blocos":[{"t":"Manobras","img":{"s":"data:image/jpeg;base64,","c":"Manobra de Israel"},"q":"Realize as manobras de palpação renal.","r":["Higienizar as mãos e pedir permissão.","Israel: paciente em decúbito lateral, palpação bimanual do rim.","Goelet: palpação bimanual do rim em decúbito dorsal."],"e":"Servem para avaliar tamanho, sensibilidade e dor da loja renal."},{"t":"Hipótese","q":"Qual a hipótese diagnóstica?","r":["Pielonefrite."],"e":"Dor lombar + febre alta + sintomas urinários baixos (disúria, polaciúria) em mulher jovem é pielonefrite aguda até prova em contrário. Solicitar urina tipo 1 e urocultura."}]},{"id":"cirrose","area":"Adulto","tema":"Fígado e baço","titulo":"Barriga volumosa, amarelo e etilista","caso":"Homem, 55 anos, cefaleia e indigestão há 15–20 dias. Esclera e língua amareladas, etilismo de 4–5 copos/dia. Aumento do volume abdominal. Realize as técnicas para ascite e verbalize a hipótese.","blocos":[{"t":"Técnicas para ascite","q":"Quais manobras você faz?","r":["Higienizar as mãos e pedir permissão.","Semicírculo de Skoda.","Sinal do piparote.","Macicez móvel."],"e":"Skoda: macicez em semicírculo de concavidade superior com timpanismo central (alças flutuantes). Piparote: onda líquida transmitida com a mão-barreira. Macicez móvel: o limite do som maciço muda com a mudança de decúbito."},{"t":"Hipótese","q":"Qual a hipótese diagnóstica?","r":["Cirrose hepática decorrente de etilismo (com ascite e icterícia)."],"e":"Icterícia + ascite + etilismo crônico formam a tríade que aponta para hepatopatia crônica descompensada."}]},{"id":"obstetrica","area":"Adulto","tema":"Gestação e ginecologia","titulo":"Pré-natal: altura uterina e Leopold","caso":"Gestante G2P1, 20 semanas, chega à UBS para consulta de pré-natal. Realize a medida da altura uterina e as manobras de Leopold.","blocos":[{"t":"Abertura","q":"O que você faz antes de examinar?","r":["Apresentar-se; confirmar nome, idade e data de nascimento.","Perguntar se há alguma queixa.","Higienizar as mãos e pedir permissão."],"e":"Aqui a anamnese é mais curta: é uma consulta de rotina."},{"t":"Altura uterina","q":"Como você mede e o que espera encontrar?","r":["Fita métrica da borda superior da sínfise púbica ao fundo uterino.","A partir da 20ª semana a altura uterina em cm coincide, em geral, com a idade gestacional."],"e":"Aos 20 semanas, esperar cerca de 20 cm. Valor muito diferente sugere erro de data, polidrâmnio/oligodrâmnio ou restrição de crescimento."},{"t":"Manobras de Leopold","q":"Quais informações as manobras fornecem?","r":["Situação, posição, apresentação e insinuação do feto.","Higienizar as mãos ao final.","Perguntar se usa sulfato ferroso.","Retorno: exame sem alterações."],"e":"Leopold avalia como o feto está dentro do útero. Sulfato ferroso é suplementação de rotina no pré-natal."}]},{"id":"mama","area":"Adulto","tema":"Gestação e ginecologia","titulo":"Nódulo na mama e história familiar","caso":"Mulher, 42 anos, ansiosa porque duas tias tiveram câncer de mama após os 40 anos. Notou recentemente um caroço na mama esquerda. Realize o exame físico completo das mamas.","blocos":[{"t":"Abertura","q":"Como você começa?","r":["Apresentar-se; identificação; queixa principal; outras queixas.","Higienizar as mãos e pedir permissão."],"e":"Antecedente familiar já aparece no enunciado e entra na decisão de exames."},{"t":"Exame","q":"Que etapas do exame das mamas você realiza?","r":["Inspeção estática e dinâmica.","Palpação das mamas (Bloodgood: ponta dos dedos; Velpeau: mão espalmada, movimentos circulares).","Cadeias linfáticas: axilares, supra e infraclaviculares e paraesternal.","Expressão papilar."],"e":"A inspeção dinâmica (braços elevados, mãos na cintura) faz aparecer retrações que a inspeção estática não mostra."},{"t":"Conduta","q":"Qual exame você solicita e como encerra?","r":["Higienizar as mãos.","Solicitar mamografia, pelos antecedentes familiares.","Tranquilizar a paciente e liberá-la."],"e":"História familiar positiva e nódulo palpável justificam imagem. Acolher a ansiedade faz parte da avaliação."}]},{"id":"papanicolau","area":"Adulto","tema":"Gestação e ginecologia","titulo":"Corrimento branco e prurido: Papanicolau","caso":"Mulher, 25 anos, vida sexual ativa, com corrimento vaginal esbranquiçado, inodoro e prurido genital intenso. Realize a colpocitologia oncótica e, pela clínica, verbalize a hipótese.","blocos":[{"t":"Abertura","q":"O que você faz?","r":["Apresentar-se; identificação; queixa principal; outras queixas.","Higienizar as mãos e pedir permissão."],"e":"Perguntar também sobre última menstruação, métodos contraceptivos e último preventivo."},{"t":"Exame especular e coleta","q":"Descreva a introdução do espéculo e a coleta.","r":["Afastar os lábios; introduzir o espéculo fechado, pino para baixo, levemente oblíquo.","Rodar para as valvas ficarem paralelas às paredes e abrir até visualizar o colo.","Ectocérvice com espátula de Ayre (giro de 180°); endocérvice com escovinha.","Passar o material na lâmina (borda fosca) e fixar."],"e":"Coletar primeiro a ectocérvice e depois a endocérvice evita ressecar o material. Teste de Schiller só depois da coleta, para não interferir no resultado."},{"t":"Achado e hipótese","q":"Você vê secreção branca grumosa aderida às paredes. Qual a hipótese?","r":["Candidíase vulvovaginal.","Higienizar as mãos; tranquilizar a paciente e liberá-la."],"e":"Corrimento branco grumoso (leite coalhado), sem odor, com prurido é típico de candidíase."}]},{"id":"colecistite","area":"Adulto","tema":"Fígado e baço","titulo":"Dor no hipocôndrio direito e no ombro","caso":"Paciente de 34 anos com dor em hipocôndrio e ombro direitos, febre baixa e vômito há 24 h. Foi pedida USG de vias biliares. Realize o sinal de Murphy e, com a USG, verbalize o diagnóstico.","blocos":[{"t":"Anamnese e manobra","q":"Quais passos? Como se faz o sinal de Murphy?","r":["Apresentar-se; identificação; queixa; outras queixas.","Higienizar as mãos e pedir permissão.","Murphy: pressão no ponto cístico (hipocôndrio direito) e pedir inspiração profunda; a dor interrompe a inspiração."],"e":"A vesícula inflamada desce ao inspirar e toca a mão do examinador: dor súbita e parada inspiratória."},{"t":"Ultrassom","img":{"s":"data:image/jpeg;base64,","c":"USG de vias biliares"},"q":"Interprete a USG e dê o diagnóstico.","r":["Colecistite aguda provocada por colelitíase."],"e":"Procure cálculo com sombra acústica, espessamento da parede e líquido pericolecístico. A dor referida no ombro direito vem da irritação do diafragma."}]},{"id":"aval-hep","area":"Adulto","tema":"Fígado e baço","titulo":"Icterícia, ascite e confusão","caso":"Paciente com icterícia e ascite há 3 meses, emagrecimento e edema de MMII. A esposa nota confusão mental e alteração do hálito. Etilismo crônico há 20 anos. Realize a hepatimetria e as manobras de Lemos Torres e Mathieu.","blocos":[{"t":"Exame","q":"Que técnicas você realiza?","r":["Apresentar-se; identificação; queixa; outras queixas.","Higienizar as mãos e pedir permissão.","Hepatimetria e manobras de Lemos Torres e Mathieu."],"e":"A hepatimetria mede a extensão hepática por percussão e palpação; Lemos Torres e Mathieu são técnicas de palpação do fígado."},{"t":"Resultado","q":"Há alterações?","r":["Hepatomegalia presente."],"e":"Confusão e foetor hepaticus (hálito) sugerem encefalopatia hepática em paciente cirrótico."}]},{"id":"baco","area":"Adulto","tema":"Fígado e baço","titulo":"Barriga inchada e vômito escuro","caso":"Paciente com abdome distendido progressivo há 4 meses, edema de MMII e astenia. Hoje, vômito escuro em grande quantidade. Etilismo por 25 anos. Realize a palpação esplênica (bimanual em decúbito dorsal e posição de Schuster, e manobra de Mathieu-Cardarelli).","blocos":[{"t":"Exame","q":"Que técnicas você realiza?","r":["Apresentar-se; identificação; queixa; outras queixas.","Higienizar as mãos e pedir permissão.","Palpação bimanual em decúbito dorsal, em Schuster e Mathieu-Cardarelli."],"e":"Schuster é o decúbito lateral direito com o braço esquerdo elevado, que aproxima o baço da parede abdominal."},{"t":"Resultado","q":"Há alterações?","r":["Esplenomegalia presente."],"e":"Esplenomegalia + ascite + vômito com sangue sugere hipertensão portal com sangramento de varizes esofágicas."}]},{"id":"hpb","area":"Adulto","tema":"Próstata","titulo":"Jato fraco aos 60 anos","caso":"Homem, 60 anos, dificuldade de esvaziar a bexiga, esforço miccional e jato fraco, pior pela manhã, com piora progressiva em 2 anos. Nega noctúria, disúria, hematúria e retenção. O pai foi operado de câncer de próstata. Realize o toque retal, verbalize os achados, a hipótese e os exames.","blocos":[{"t":"Abertura","q":"Como você começa?","r":["Apresentar-se; identificação; queixa; outras queixas.","Higienizar as mãos e pedir permissão."],"e":"Perguntar sempre por antecedente familiar de câncer de próstata, que aparece aqui."},{"t":"Toque retal","q":"O que você encontra e verbaliza?","r":["Próstata aumentada, sem nodulações, de consistência elástica."],"e":"Consistência elástica e sem nódulos favorece hiperplasia benigna. Pedra lenhosa ou nódulo endurecido sugere câncer."},{"t":"Hipótese e exame","q":"Qual a hipótese e o que solicita?","r":["Hiperplasia prostática benigna (HPB).","Solicitar dosagem do PSA.","Tranquilizar o paciente."],"e":"A história familiar de câncer de próstata justifica dosar o PSA mesmo com toque benigno."}]},{"id":"ce","area":"Pediatria","tema":"Corpo estranho","titulo":"Menina de 5 anos engoliu parte de um brinquedo","caso":"Menina de 5 anos, ingestão de um pedaço de brinquedo há 3 horas. Sem vômitos ou salivação excessiva. Rx de tórax e abdome na imagem. Avalie o Rx, verbalize o objeto e a conduta.","blocos":[{"t":"Anamnese","q":"O que você pergunta?","r":["Identificar-se; confirmar o nome do paciente e a queixa.","Outros sintomas: disfagia, odinofagia, dor retroesternal, tosse."],"e":"Sintomas respiratórios ou salivação indicam impactação esofágica e urgência."},{"t":"Radiografia","img":{"s":"data:image/jpeg;base64,","c":"Radiografia de tórax e abdome"},"q":"O que você observa? Qual o objeto?","r":["Sinal do duplo halo (contorno duplo).","Objeto: bateria."],"e":"A bateria tem uma borda dupla (duplo halo) e, de perfil, um degrau na borda. A moeda é um disco homogêneo, sem duplo contorno."},{"t":"Conduta","q":"Qual a conduta e por quê?","r":["Retirada por endoscopia digestiva alta (EDA).","Motivo: lesão cáustica, necrose por pressão direta e descarga elétrica.","Despedir-se e passar o caso ao preceptor."],"e":"Bateria em esôfago é emergência: a corrente elétrica gera hidróxido e queimadura em poucas horas."}]},{"id":"constip","area":"Pediatria","tema":"Constipação e diarreia","titulo":"Criança de 8 anos perdendo fezes na roupa","caso":"Menino, 8 anos, perde fezes nas roupas há 1 ano. Evacua 2 vezes por semana, fezes que entopem o vaso. Realize o exame físico abdominal e verbalize os achados, o diagnóstico e a conduta.","blocos":[{"t":"Anamnese","q":"Que outros sintomas você pesquisa?","r":["Identificar-se; confirmar nome e queixa.","Parada de eliminação de fezes, sangue nas fezes, vômitos, dor abdominal, retenção urinária, irritabilidade e mudança comportamental."],"e":"Procurar sinais de alerta (retardo de mecônio, vômitos biliosos, sangue, falha de crescimento) para diferenciar constipação orgânica de funcional."},{"t":"Exame abdominal","q":"Quais os achados?","r":["Higienizar as mãos e pedir permissão.","Inspeção: distensão abdominal.","Ausculta: RHA aumentados.","Palpação: massa palpável no hipogástrio (fecaloma).","Percussão: timpanismo.","Toque retal (opcional): ampola com grande quantidade de fezes endurecidas."],"e":"O fecaloma palpável em hipogástrio indica retenção fecal crônica."},{"t":"Diagnóstico e conduta","q":"Qual o diagnóstico e o que você orienta?","r":["Constipação intestinal funcional.","Desimpactação, tratamento laxativo prolongado com terapia comportamental, mudanças alimentares, redução e retirada gradual dos laxantes."],"e":"A perda de fezes na roupa (escape fecal) é consequência da retenção e do transbordamento, e não diarreia."}]},{"id":"diarreia","area":"Pediatria","tema":"Constipação e diarreia","titulo":"Diarreia aquosa e desidratação","caso":"Menino, 9 anos e 6 meses, com mais de 7 evacuações diarreicas aquosas em 24 h, sem muco ou sangue. Irritado, olhos fundos, prega de 3 segundos, mucosas muito secas, enchimento capilar > 5 s. Determine o grau de desidratação, a conduta e as orientações.","blocos":[{"t":"Anamnese","q":"O que você pergunta?","r":["Identificar-se; confirmar nome e queixa.","Vômitos, febre, inapetência, dor abdominal."],"e":"Vômitos podem atrapalhar a reidratação oral."},{"t":"Classificação","img":{"s":"data:image/jpeg;base64,","c":"Avaliação do estado de hidratação"},"q":"Qual o grau de desidratação?","r":["Desidratado — Plano B."],"e":"Irritabilidade, olhos fundos, prega lenta e mucosas secas classificam o Plano B (desidratação). Sinais graves (letargia, incapacidade de beber, prega > 2 s com choque) levam ao Plano C."},{"t":"Conduta e orientações","q":"Qual a conduta e as orientações?","r":["Terapia de reidratação oral (TRO), 50–100 mL/kg em 4–6 horas, na unidade de saúde.","Higiene pessoal e domiciliar: lavar as mãos, tratar a água e higienizar os alimentos."],"e":"Reavaliar a criança ao longo da TRO: se melhorar, vai para o Plano A; se piorar, para o C."}]},{"id":"ictericia","area":"Pediatria","tema":"Fígado e icterícia","titulo":"Recém-nascido de 25 dias com fezes brancas","caso":"RN a termo, 25 dias, icterícia desde a segunda semana, com piora progressiva. Há 3 dias, urina escura e fezes esbranquiçadas. BEG, ictérico 4+/4. Realize a palpação hepática e verbalize a hipótese.","blocos":[{"t":"Palpação","q":"Que manobras você realiza?","r":["Identificar-se; confirmar nome e queixa.","Higienizar as mãos e pedir permissão.","Palpação hepática: manobras de Lemos Torres e Mathieu."],"e":"A palpação serve para avaliar tamanho e consistência do fígado."},{"t":"Hipótese","q":"Qual a hipótese diagnóstica?","r":["Icterícia patológica (> 2 semanas, colúria e acolia fecal): colestática.","Passar o caso ao preceptor: exames complementares são necessários."],"e":"Colúria e acolia mostram que a bilirrubina conjugada não chega ao intestino: suspeitar atresia de vias biliares, que exige diagnóstico e Kasai precoces."}]},{"id":"itu1","area":"Pediatria","tema":"Urologia pediátrica","titulo":"Febre e dor no flanco aos 5 anos","caso":"Menina de 5 anos, UBS, febre de 39 °C, dor no flanco direito, leve tontura e náuseas. Realize Giordano, Credé e palpação da bexiga, verbalize a hipótese e solicite exames.","blocos":[{"t":"Anamnese","q":"Que sintomas você pergunta?","r":["Identificar-se; confirmar nome e queixa.","Disúria, polaciúria, irradiação da dor, vômitos."],"e":"Em criança pequena os sintomas urinários podem faltar; febre sem foco deve sugerir ITU."},{"t":"Manobras","img":{"s":"data:image/jpeg;base64,","c":"Manobra de Credé"},"q":"Que manobras você faz?","r":["Higienizar as mãos e pedir permissão.","Giordano, Credé (compressão vesical) e palpação da bexiga."],"e":"Giordano avalia dor renal e Credé, a compressão suprapúbica da bexiga."},{"t":"Hipótese e exames","q":"Qual a hipótese e quais exames?","r":["ITU alta — pielonefrite.","Urina tipo 1 e urocultura."],"e":"Febre alta com dor em flanco indica comprometimento do parênquima renal."}]},{"id":"itu2","area":"Pediatria","tema":"Urologia pediátrica","titulo":"Dor lombar e urina escura aos 10 anos","caso":"Criança de 10 anos com dor lombar direita há 2 dias, náuseas e vômitos. Há 1 dia, urina escura, disúria, polaciúria, febre, mal-estar e inapetência. REG, 39 °C. Realize as manobras de Trousseau, Glenard e Bellington e verbalize a hipótese.","blocos":[{"t":"Manobras","q":"Que manobras você realiza?","r":["Identificar-se; confirmar nome e queixa.","Disúria, polaciúria, irradiação da dor, vômitos.","Higienizar as mãos e pedir permissão.","Manobras de Trousseau, Glenard e Bellington."],"e":"São manobras de palpação renal. O objetivo é avaliar o rim e a loja renal."},{"t":"Hipótese","q":"Qual a hipótese?","r":["ITU alta — pielonefrite."],"e":"A mesma lógica da estação anterior: febre alta + dor lombar + sintomas urinários."}]},{"id":"apendicite-ped","area":"Pediatria","tema":"Abdome agudo","titulo":"Dor abdominal, febre e vômitos aos 4 anos","caso":"Criança de 4 anos, dor abdominal que se intensificou nas últimas 6 h, febre há 36 h e vômitos há 24 h. Pensando em apendicite, teste o sinal de Rovsing, encontre o ponto de McBurney e teste o sinal de Blumberg.","blocos":[{"t":"Preparação","q":"Como você se posiciona e prepara a criança?","r":["Identificar-se; confirmar nome e queixa com o responsável.","Higienizar as mãos.","Posicionar-se do lado direito do paciente.","Explicar que vai tocar na barriga e que pode doer um pouco."],"e":"Na criança, explicar o procedimento reduz resistência voluntária da parede abdominal."},{"t":"Manobras","img":{"s":"data:image/jpeg;base64,","c":"Localização da dor da apendicite"},"q":"Descreva Rovsing, McBurney e Blumberg.","r":["Rovsing: palpar o quadrante inferior esquerdo e o paciente sente dor no direito.","McBurney: linha entre cicatriz umbilical e espinha ilíaca ântero-superior, dividida em 3 partes; o ponto está entre o terço médio e o distal.","Blumberg: comprimir McBurney e soltar de repente; dor à descompressão indica apendicite."],"e":"Esses sinais indicam irritação peritoneal na fossa ilíaca direita."}]},{"id":"glomerulo","area":"Pediatria","tema":"Urologia pediátrica","titulo":"Edema periorbitário que evolui para anasarca","caso":"Criança de 5 anos com edema que começou na região periorbitária e evoluiu para anasarca. O preceptor pede que você verifique o sinal do piparote e do cacifo.","blocos":[{"t":"Exame","img":{"s":"data:image/jpeg;base64,","c":"Sinal do piparote (ascite) e do cacifo (edema)"},"q":"Que sinais você pesquisa e como?","r":["Identificar-se; identificar o paciente com o responsável; confirmar a queixa.","Higienizar as mãos e pedir permissão.","Cacifo: pressionar a pele sobre osso (tíbia) e ver se fica a depressão.","Piparote: o toque lateral do flanco gera onda líquida sentida do outro lado (ascite)."],"e":"Edema com cacifo e ascite compõem anasarca, característica de síndrome nefrótica/nefrítica."},{"t":"Retorno ao responsável","q":"Como você encerra?","r":["Higienizar as mãos.","Dar o feedback ao responsável com os achados do exame."],"e":"Edema periorbitário matinal que generaliza deve levar a pesquisar urina (proteinúria, hematúria) e pressão arterial."}]},{"id":"sinequia","area":"Pediatria","tema":"Urologia pediátrica","titulo":"Pequenos lábios fundidos aos 2 anos","caso":"A mãe de uma menina de 2 anos notou, ao higienizar, que os pequenos lábios estão fundidos. Você deve revelar o diagnóstico e orientar a mãe.","blocos":[{"t":"Anamnese e exame","q":"O que você pergunta e faz?","r":["Identificar-se; confirmar nome e queixa.","Perguntar irritabilidade, disúria, gotejamento urinário, história de ITU.","Higienizar as mãos; pedir permissão; avaliar a genitália."],"e":"A sinéquia pode causar gotejamento urinário e ITU de repetição."},{"t":"Diagnóstico e orientação","img":{"s":"data:image/jpeg;base64,","c":"Fusão dos pequenos lábios"},"q":"Qual o diagnóstico e o que você orienta?","r":["Sinéquia de pequenos lábios.","Autorresolutiva na maioria dos casos (hipoestrogenismo, higiene, pequenos traumas, irritantes, vulvovaginites).","Assintomática: conduta expectante.","Sintomática: estrogênio tópico.","Cirurgia: sem resposta clínica ou obstrução do fluxo urinário."],"e":"A fusão costuma se resolver espontaneamente com o estímulo estrogênico da puberdade."}]},{"id":"torcao","area":"Pediatria","tema":"Urologia pediátrica","titulo":"Dor testicular súbita aos 12 anos","caso":"Menino de 12 anos, hígido, dor testicular direita intensa de início abrupto, náuseas e vômitos há 5 h. Bom estado geral, dor intensa à palpação e edema acentuado. O hospital não tem imagem, mas tem centro cirúrgico. Realize a palpação testicular, avalie o reflexo cremastérico, verbalize a hipótese e a conduta.","blocos":[{"t":"Anamnese e exame","q":"O que você pergunta e encontra?","r":["Identificar-se; confirmar nome e queixa; perguntar sobre movimentos que possam ter causado.","Higienizar as mãos; pedir permissão.","Testículo direito horizontalizado e elevado.","Reflexo cremastérico ausente."],"e":"Testículo alto e horizontalizado com reflexo cremastérico ausente é o conjunto clássico da torção. A escala de Tanner também deve ser lembrada."},{"t":"Hipótese e conduta","img":{"s":"data:image/jpeg;base64,","c":"Aspecto da bolsa escrotal"},"q":"Qual a hipótese e a conduta?","r":["Torção testicular.","Encaminhar com urgência à cirurgia."],"e":"É emergência com janela de cerca de 6 horas: sem imagem disponível, não atrasar a exploração cirúrgica."}]},{"id":"fissura","area":"Pediatria","tema":"Aleitamento","titulo":"Dor e fissura mamária no 4º dia de puerpério","caso":"Primípara, 4º dia de puerpério após cesárea (feto pélvico, 36 semanas), no alojamento conjunto. Dor mamária intensa. Temperatura 38 °C, dor, hiperemia leve e aumento de volume nas mamas, fissura à esquerda, mamas endurecidas nos quadrantes externos, expressão láctea positiva. Oriente a pega correta e a conduta nas fissuras.","blocos":[{"t":"Pega correta","img":{"s":"data:image/jpeg;base64,","c":"Sinais da pega correta"},"q":"Quais os sinais da pega correta?","r":["Boca bem aberta, como 'boquinha de peixe'.","Lábio inferior voltado para fora.","Maior parte da aréola abocanhada, mais visível acima do lábio superior.","Queixo encostado no seio; narinas livres.","Bochechas cheias; sucção lenta e profunda."],"e":"A pega incorreta, com bebê abocanhando só o mamilo, é a principal causa de fissura."},{"t":"Conduta na fissura","q":"Qual a conduta?","r":["Corrigir pega e posição.","Antes da mamada, retirar um pouco de leite se a mama estiver ingurgitada.","Manter o aleitamento.","Passar o próprio leite no mamilo após a mamada e deixar secar."],"e":"Não suspender a amamentação: o esvaziamento da mama previne mastite. Febre com mama endurecida exige acompanhar sinais de ingurgitamento/mastite."}]},{"id":"hep-b-aguda","area":"Adulto","tema":"Hepatites","titulo":"Icterícia aguda em jovem","caso":"Homem, 26 anos, pródromo há 10 dias; há 4 dias, icterícia, colúria e acolia. Relação sexual sem preservativo há 2 meses. Nega álcool e medicamentos. Lúcido, sem flapping, fígado doloroso.","blocos":[{"t":"Anamnese e exame","q":"O que você pergunta e examina?","r":["Higienizar as mãos e apresentar-se.","Sintomas: icterícia, colúria, acolia, prurido, febre, dor em hipocôndrio direito, pródromo e tempo de evolução.","Exposições: água/alimento, sexo desprotegido, drogas, tatuagem, transfusão antes de 1993, hemodiálise, profissão de saúde, mãe portadora.","Álcool (CAGE/AUDIT), medicamentos e chás; vacinação para hepatites A e B.","Exame: icterícia (escleras e freio lingual), consciência e flapping, estigmas de hepatopatia, hepatimetria, baço, ascite e Murphy."],"e":"Esta é a abertura clássica de hepatite: exposição + álcool/medicamentos + sinais de gravidade (flapping e consciência)."},{"t":"Exames","ctx":"Resultados: ALT 1.850, AST 1.400, bilirrubina total 8 (direta 6), INR 1,1. HBsAg +, anti-HBc IgM +, HBeAg +, anti-HBs −; anti-HAV IgM −; anti-HCV −.","q":"Que exames você pede e o que mostram?","r":["Pedir: ALT, AST, FA, GGT, bilirrubinas, INR, albumina, hemograma, glicemia, anti-HAV IgM, HBsAg, anti-HBc IgM, anti-HCV, HIV, sífilis e USG.","Hepatite B aguda em fase replicativa (HBsAg + e anti-HBc IgM +, HBeAg +).","Sem sinais de gravidade: INR normal e sem encefalopatia."],"e":"ALT > 1.000 sugere hepatite viral aguda, tóxica, isquêmica ou autoimune. INR e consciência medem a função hepática; a transaminase não mede função."},{"t":"Diagnóstico e conduta","q":"Qual o diagnóstico e a conduta?","r":["Hepatite B aguda, sem sinais de gravidade.","Suporte ambulatorial, sem álcool e hepatotóxicos; ALT, bilirrubina e INR seriados.","Retorno imediato se confusão, sangramento ou vômitos.","Notificação compulsória; testar HIV, sífilis e HCV.","Parceira: testar; se suscetível, vacina + imunoglobulina.","HBsAg em 6 meses: negativo com anti-HBs + = cura; positivo = crônica."],"e":"Internar se INR ≥ 1,5, encefalopatia, vômitos incoercíveis, hipoglicemia, gestante ou idoso frágil. Paracetamol no máximo 2 g/dia."}]},{"id":"hep-c-cronica","area":"Adulto","tema":"Hepatites","titulo":"Anti-HCV positivo no rastreio","caso":"Mulher, 52 anos, assintomática, transfusão em 1988. Teste rápido anti-HCV reagente. HCV-RNA 1,2 milhão UI/mL. ALT 70, AST 52, plaquetas 210 mil (APRI 0,6; FIB-4 1,5); USG normal. HBsAg, anti-HBc, anti-HBs e HIV negativos. Usa omeprazol 40 mg.","blocos":[{"t":"Interpretação","q":"O que significa o resultado e qual o diagnóstico?","r":["Anti-HCV reagente, confirmado por HCV-RNA detectável: infecção ativa.","Hepatite C crônica com viremia, sem cirrose (APRI 0,6 e FIB-4 1,5, USG normal)."],"e":"O anti-HCV fica positivo mesmo após a cura; por isso confirma-se sempre com o HCV-RNA. A transfusão antes de 1993 é fator de risco."},{"t":"Tratamento","q":"Qual o tratamento e o cuidado com os medicamentos dela?","r":["Tratar todos com HCV-RNA detectável.","Sofosbuvir/velpatasvir 1 comprimido ao dia por 12 semanas (ou glecaprevir/pibrentasvir por 8 semanas).","Revisar o omeprazol: reduzir ou suspender, pela interação com o velpatasvir."],"e":"Antivirais de ação direta curam mais de 95%. Interações importantes: IBP reduz velpatasvir; amiodarona + sofosbuvir causa bradicardia grave; indutores (rifampicina, carbamazepina)."},{"t":"Orientações","q":"Quais orientações e metas?","r":["Vacinar para hepatite B (suscetível) e checar a hepatite A.","Sem álcool.","Cura = HCV-RNA indetectável 12 semanas após o fim do tratamento (RVS12).","O anti-HCV continuará positivo; a reinfecção é possível.","Notificar."],"e":"Antes de tratar, checar HBsAg e anti-HBc pelo risco de reativação da hepatite B."}]},{"id":"hep-sorologia","area":"Adulto","tema":"Hepatites","titulo":"Interprete as sorologias da hepatite B","caso":"Você recebe os resultados de três pacientes que fizeram sorologia para hepatite B. O examinador pede que você interprete cada um. Lembre: HBsAg = tem o vírus; anti-HBc IgM = agudo; anti-HBc total = contato; HBeAg = replicação; anti-HBs = imunidade.","blocos":[{"t":"Paciente A","tab":{"h":["Marcador","Resultado"],"l":[["HBsAg","Reagente"],["Anti-HBc IgM","Não reagente"],["Anti-HBc total","Reagente"],["HBeAg","Reagente"],["Anti-HBe","Não reagente"],["Anti-HBs","Não reagente"]]},"q":"Interprete a sorologia do paciente A.","r":["HBsAg reagente com IgM não reagente e anti-HBc total reagente: infecção não recente.","Se o HBsAg persiste por 6 meses ou mais: crônica.","HBeAg reagente: alta replicação.","Hepatite B crônica HBeAg positivo."],"e":"Crônica = HBsAg positivo por 6 meses ou mais. Pedir HBV-DNA, ALT e avaliação de fibrose para decidir tratamento."},{"t":"Paciente B","tab":{"h":["Marcador","Resultado"],"l":[["HBsAg","Não reagente"],["Anti-HBc IgM","Não reagente"],["Anti-HBc total","Reagente"],["HBeAg","Não reagente"],["Anti-HBe","Reagente"],["Anti-HBs","Reagente"]]},"q":"Interprete a sorologia do paciente B.","r":["HBsAg não reagente, anti-HBs e anti-HBc total reagentes.","Infecção passada, curada."],"e":"Diferente do vacinado, que tem apenas anti-HBs positivo."},{"t":"Paciente C","tab":{"h":["Marcador","Resultado"],"l":[["HBsAg","Não reagente"],["Anti-HBc IgM","Não reagente"],["Anti-HBc total","Não reagente"],["HBeAg","Não reagente"],["Anti-HBe","Não reagente"],["Anti-HBs","Reagente"]]},"q":"Interprete a sorologia do paciente C.","r":["Somente anti-HBs reagente.","Vacinado (imune)."],"e":"Nunca teve contato com o vírus. Se nenhum marcador for positivo, o paciente é suscetível: vacinar."}]},{"id":"spikes-biopsia","area":"Adulto","tema":"Comunicação de más notícias (SPIKES)","titulo":"Resultado de biópsia de mama","caso":"Mulher, 52 anos, professora, veio sozinha buscar o resultado da biópsia de um nódulo na mama: carcinoma ductal invasivo. Ansiosa, pergunta na porta: “Doutor, deu alguma coisa ruim?”. Na sala, após a notícia, começa a chorar e diz: “Não pode ser, eu tenho dois filhos pequenos”.","blocos":[{"t":"S e P: preparar e perceber","q":"O que você faz antes de dar a notícia?","r":["Levá-la à sala, sentar, oferecer chamar alguém.","Apresentar-se e confirmar a identidade.","Perguntar o que ela sabe: “O que a senhora sabe sobre a biópsia?”."],"e":"S = Setting (ambiente privado, sentado, na altura dos olhos, celular silencioso). P = Perception: perguntar antes de falar corrige mal-entendidos."},{"t":"I e K: convite e conhecimento","q":"Como você conduz a conversa e dá a notícia?","r":["Convite: “Como prefere que eu explique?”.","Aviso prévio (“tiro de aviso”): “infelizmente, não tenho boas notícias”.","Dizer em linguagem simples: “o exame mostrou um câncer de mama”.","Em pequenas partes, sem jargão, com pausas; verificar o entendimento."],"e":"Evitar jargão (“neoplasia”) e não dar falsa esperança nem dizer “não há mais nada a fazer”."},{"t":"E: emoções","q":"Ela chora e fala dos filhos. O que você responde?","r":["Silêncio, oferecer lenço; não interromper o choro.","Nomear a emoção: “vejo que pensar nos seus filhos dói muito”.","Usar NURSE: nomear, compreender, respeitar, apoiar, explorar."],"e":"Não tente “resolver” a emoção nem diga “eu sei como se sente”. Acolher é a conduta."},{"t":"S: estratégia e resumo","q":"Como você encerra?","r":["Explicar que há tratamento e os próximos exames (imuno-histoquímica, estadiamento).","Encaminhamento prioritário à mastologia/oncologia; psicologia e rede de apoio.","Resumir, marcar retorno e ficar disponível."],"e":"Mantenha a esperança realista e deixe claro que a equipe continuará cuidando (não abandono)."}]},{"id":"spikes-obito","area":"Adulto","tema":"Comunicação de más notícias (SPIKES)","titulo":"Óbito no pronto-socorro","caso":"Homem, 70 anos, cardiopata, chegou ao PS em parada cardiorrespiratória; após 40 minutos de reanimação, evoluiu a óbito. A filha acabou de chegar, aflita, na recepção: “Cadê meu pai? Ele está bem?”.","blocos":[{"t":"Ambiente e percepção","q":"Onde e como você começa a conversa?","r":["Não falar na recepção: levar a uma sala reservada, sentar.","Apresentar-se, confirmar o vínculo e perguntar se quer alguém junto.","Perguntar o que já sabe."],"e":"Nunca dar a notícia em pé, no corredor ou na recepção."},{"t":"A notícia","q":"Como você comunica o óbito?","r":["Aviso prévio: “seu pai chegou muito grave, o coração tinha parado…”.","Dizer com clareza: “infelizmente, ele morreu, apesar de todo o esforço da equipe”.","Silêncio e acolhimento."],"e":"Use as palavras “morreu”/“faleceu”. Evite eufemismos como “descansou” ou “partiu”, que geram dúvida."},{"t":"Depois da notícia","q":"Que orientações e encaminhamentos você faz?","r":["Explicar o que foi feito e oferecer ver o corpo.","Acionar serviço social e psicologia.","Orientar a declaração de óbito: morte natural com causa provável, o médico emite; sem causa definida, SVO.","Ficar disponível para perguntas."],"e":"A declaração de óbito é detalhada em resumo próprio."}]},{"id":"abd-apendicite-caso","area":"Adulto","tema":"Abdome agudo","titulo":"Apendicite em jovem de 21 anos","caso":"Homem, 21 anos, dor periumbilical há 18 h que migrou para a fossa ilíaca direita, com anorexia e náusea. T 38,1 °C, FC 104. Palpação superficial: defesa em FID. Profunda: dor máxima em McBurney; Blumberg +, Rovsing +, psoas −. Leucócitos 15.800 com desvio. EAS normal. Alvarado 10. USG: apêndice de 9 mm, não compressível.","blocos":[{"t":"Diagnóstico","q":"Qual o diagnóstico e o que sustenta?","r":["Abdome agudo inflamatório: apendicite aguda não complicada.","Migração da dor + anorexia + febre; Blumberg e Rovsing positivos.","Leucocitose com desvio; Alvarado 10; USG com apêndice > 6 mm e não compressível."],"e":"Alvarado alto (≥ 7–9) com quadro típico já permite decidir pela cirurgia. Em mulher, pedir β-hCG antes."},{"t":"Conduta","q":"Qual a conduta?","r":["Jejum, hidratação, analgesia (dipirona + opioide) e antiemético.","Profilaxia antibiótica pré-incisão: cefazolina 2 g + metronidazol 500 mg IV.","Apendicectomia laparoscópica.","Sem antibiótico no pós-operatório se não complicada (perfurada: por cerca de 4 dias)."],"e":"Analgesia precoce não mascara o exame e deve ser feita. Chamar o cirurgião."}]},{"id":"abd-bridas-caso","area":"Adulto","tema":"Abdome agudo","titulo":"Distensão e parada de gases em mulher de 64 anos","caso":"Mulher, 64 anos, histerectomia há 10 anos. Cólica difusa há 2 dias, vômitos e parada de eliminação de gases e fezes. Afebril, FC 96. Inspeção: cicatriz e distensão. Ausculta: RHA aumentados, timbre metálico. Percussão: timpanismo. Palpação: dor difusa leve, sem defesa nem descompressão dolorosa. K 3,1, lactato 1,3. RX: níveis hidroaéreos em escada, empilhamento de moedas. TC: ponto de transição no delgado, sem isquemia.","blocos":[{"t":"Diagnóstico","q":"Qual o diagnóstico?","r":["Abdome agudo obstrutivo: obstrução de delgado por bridas, sem sinais de estrangulamento."],"e":"Cirurgia prévia + RHA metálicos + níveis em escada + ponto de transição na TC. Sem febre, taquicardia, peritonite ou lactato elevado = sem sofrimento de alça."},{"t":"Conduta clínica","q":"Qual o tratamento inicial?","r":["Jejum, SNG aberta, cristaloide e repor potássio.","Sonda vesical (controle de diurese), analgesia e antiemético.","Contraste hidrossolúvel 100 mL pela SNG e RX em 6–24 h."],"e":"Se o contraste chegou ao cólon, a obstrução está resolvendo: iniciar dieta."},{"t":"Quando operar","q":"Quando indicar cirurgia?","r":["Contraste não progrediu.","Febre, taquicardia, peritonite ou lactato elevado.","Cirurgia: lise de bridas."],"e":"Esses sinais sugerem isquemia ou estrangulamento e não toleram espera."}]},{"id":"ger-polifarmacia","area":"Adulto","tema":"Avaliação geriátrica","titulo":"Quedas, esquecimento e polifarmácia","caso":"Mulher, 82 anos, 4 anos de estudo, trazida pela filha: 2 quedas em 6 meses e esquecimento progressivo há 2 anos; perdeu 5 kg. Usa 8 medicamentos, incluindo diazepam, amitriptilina, anlodipino e hidroclorotiazida. PA deitada 140/80 → em pé (3 min) 115/70. TUG 18 s, preensão 14 kg, panturrilha 29 cm. MEEM 19, GDS 4. Katz independente; Lawton: dependente para remédios e finanças. MAN 9.","blocos":[{"t":"Abordagem","q":"Como você conduz a conversa e o exame?","r":["Comunicação respeitando a autonomia: “vou fazer algumas perguntas sobre o seu dia a dia”.","Lista completa de medicações.","PA deitada e em pé; TUG cronometrado e marcha observada.","Katz e Lawton; MEEM ajustado pela escolaridade."],"e":"Katz mede as atividades básicas e Lawton as instrumentais (remédios, finanças). Com 4 anos de estudo, o ponto de corte do MEEM é menor."},{"t":"Diagnóstico","q":"Qual o diagnóstico, com justificativa?","r":["Síndrome da fragilidade com sarcopenia e risco nutricional (preensão baixa, TUG 18 s, panturrilha 29 cm, perda de peso, MAN 9).","Quedas multifatoriais: hipotensão ortostática iatrogênica e medicações inapropriadas pelos critérios de Beers.","Provável síndrome demencial (déficit cognitivo com perda de AIVD)."],"e":"A queda de PA em pé (140/80 → 115/70) com anti-hipertensivos e psicotrópicos aponta a causa iatrogênica."},{"t":"Conduta","q":"Qual a conduta?","r":["Desprescrever: retirar diazepam gradualmente e a amitriptilina; rever os anti-hipertensivos.","Investigar causas reversíveis: B12, TSH, VDRL, hemograma, glicemia, função renal, eletrólitos, cálcio, TC/RM de crânio.","Fisioterapia (força e equilíbrio), dieta rica em proteína, vitamina D se baixa, densitometria, oftalmologia.","Adaptar a casa (tapetes, barras, luz), orientar a família e seguimento interdisciplinar."],"e":"Resposta completa sempre tem diagnóstico, justificativa e conduta."}]},{"id":"ger-delirium","area":"Adulto","tema":"Avaliação geriátrica","titulo":"Confusão aguda em idoso","caso":"Homem, 78 anos, trazido pela esposa: há 2 dias confuso, sonolento de dia e agitado à noite, com flutuação. Há 4 dias começou difenidramina para dormir. Antes, independente e lúcido. T 37,8 °C, FC 104. Desatento (não diz os meses de trás para frente), fala desconexa. Globo vesical palpável. EAS com leucocitúria e nitrito +.","blocos":[{"t":"Diagnóstico","q":"Qual o diagnóstico e a causa provável?","r":["Delirium (CAM positivo).","Precipitado por retenção urinária com ITU, desencadeada por anticolinérgico (difenidramina)."],"e":"Início agudo, flutuação, desatenção e alteração do nível de consciência diferenciam delirium de demência."},{"t":"Conduta","q":"Qual a conduta?","r":["Tratar a causa: suspender a difenidramina, sondagem vesical de alívio, urocultura e antibiótico, hidratação.","Medidas não farmacológicas (1ª linha): reorientação, família presente, óculos/aparelho auditivo, ciclo sono-vigília, mobilização precoce, evitar contenção.","Haloperidol em dose baixa (0,5–1 mg) só se agitação com risco; evitar benzodiazepínico.","Não aplicar MEEM agora; reavaliar a cognição após a resolução."],"e":"A cognição só pode ser testada com o paciente fora do delirium."}]},{"id":"prenatal-atraso","area":"Adulto","tema":"Gestação e ginecologia","titulo":"Atraso menstrual na UBS","caso":"Mulher, 26 anos, G1P0, DUM 01/03 (certa, ciclos regulares), consulta em 19/04: náuseas, mastalgia, polaciúria. Teste rápido de gravidez positivo. Nunca fez citopatológico. PA 110/70, IMC 23. Especular: vagina e colo violáceos. Toque: útero aumentado e amolecido (Hegar +), anexos livres, sem dor.","blocos":[{"t":"Acolhimento e cálculos","q":"Como você recebe a notícia e qual a IG e a DPP?","r":["“Parabéns, o teste deu positivo. Como você se sente com essa notícia?”","IG de 7 semanas pela DUM.","DPP 08/12 (regra de Naegele: DUM + 7 dias e − 3 meses)."],"e":"Violáceo (Chadwick) e Hegar são sinais de probabilidade de gravidez."},{"t":"Diagnóstico","q":"Qual o diagnóstico?","r":["Gestação de 7 semanas pela DUM, de risco habitual."],"e":"Sem comorbidades, idade 26 anos, IMC normal e PA normal: risco habitual."},{"t":"Conduta","q":"Qual a conduta?","r":["Entregar a caderneta; coletar o citopatológico (26 anos, nunca fez; pode na gestação).","Exames do 1º trimestre e USG (datação).","Ácido fólico 0,4 mg + ferro 40 mg/dia.","Vacinas: hepatite B se suscetível, influenza, COVID; dTpa com 20 semanas.","Sinais de alarme (sangramento, dor), hábitos, consulta odontológica e retorno em 4 semanas."],"e":"Na coleta do citopatológico: espátula na metade superior, escova na inferior e fixar já."}]},{"id":"prenatal-exames","area":"Adulto","tema":"Gestação e ginecologia","titulo":"Retorno com exames alterados","caso":"Mulher, 32 anos, G3P1A1, 10 semanas, sem queixas. Teste rápido de sífilis reagente; VDRL 1:16 (nunca tratou; sem lesões). Glicemia de jejum 98 mg/dL. Tipagem O Rh negativo, Coombs indireto negativo. HIV, HBsAg e anti-HCV não reagentes. Hb 11,8. Urocultura negativa. Parceiro não testado.","blocos":[{"t":"Diagnóstico","q":"Que diagnósticos você faz?","r":["Gestação de 10 semanas com sífilis latente de duração indeterminada.","Diabetes gestacional (glicemia de jejum 98 mg/dL, acima de 92).","Rh negativo não sensibilizada (Coombs indireto negativo)."],"e":"Sífilis latente sem lesões e sem data de infecção é “de duração indeterminada”."},{"t":"Sífilis","q":"Qual o tratamento da sífilis?","r":["Penicilina benzatina 2,4 milhões UI IM, 1 vez por semana por 3 semanas (total 7,2 milhões UI).","Notificar; testar e tratar o parceiro.","VDRL mensal."],"e":"Penicilina é o único tratamento adequado para prevenir sífilis congênita."},{"t":"DMG e Rh","q":"E o diabetes gestacional e o Rh negativo?","r":["DMG: orientação nutricional, atividade física, perfil glicêmico; insulina se fora da meta.","Encaminhar ao pré-natal de alto risco mantendo o acompanhamento na UBS.","Rh negativo: repetir Coombs com 28 semanas e aplicar imunoglobulina anti-D; também após sangramento e no pós-parto se RN Rh+."],"e":"A imunoglobulina anti-D previne a sensibilização da mãe Rh negativa."}]},{"id":"disp-sem-alarme","area":"Adulto","tema":"DRGE e dispepsia","titulo":"Queimação que melhora ao comer","caso":"Homem, 32 anos, queimação epigástrica há 5 meses, melhora ao comer, acorda à noite com dor. Usa ibuprofeno 3×/semana por lombalgia. Sem perda de peso, sangramento ou disfagia; sem história familiar. Dor leve à palpação do epigástrio. Teste respiratório com ureia positivo.","blocos":[{"t":"Anamnese","q":"O que você pergunta?","r":["Se a dor melhora ou piora ao comer.","Sinais de alarme: perda de peso, sangramento, disfagia, vômitos, anemia, história familiar de câncer gástrico.","Uso de AINE.","Excluir causa cardíaca e biliar."],"e":"Sem sinais de alarme e abaixo dos 45–60 anos, a estratégia é testar e tratar, e não pedir endoscopia de cara."},{"t":"Diagnóstico","q":"Qual o diagnóstico?","r":["Dispepsia não investigada, sem alarme, com H. pylori positivo e uso de AINE.","Suspeita de úlcera duodenal."],"e":"Dor que melhora ao comer e acorda à noite é típica de úlcera duodenal."},{"t":"Conduta","q":"Qual o tratamento e as orientações?","r":["Suspender o ibuprofeno (trocar por paracetamol ou dipirona).","Quádrupla com bismuto por 14 dias: omeprazol 40 mg 12/12 h + bismuto 240 mg 12/12 h + metronidazol 400 mg 6/6 h + tetraciclina 500 mg 6/6 h.","Avisar: fezes escuras, sem álcool, adesão.","Controle de cura com teste respiratório 4 semanas ou mais após, sem IBP há 2 semanas.","Persistindo os sintomas → IBP; se falhar → EDA."],"e":"Bismuto escurece as fezes; é importante avisar para não ser confundido com melena."}]},{"id":"disp-alarme","area":"Adulto","tema":"DRGE e dispepsia","titulo":"Saciedade precoce e perda de 7 kg","caso":"Homem, 63 anos, plenitude e saciedade precoce há 3 meses, perda de 7 kg, vômitos ocasionais. Pai teve câncer gástrico. Palidez; linfonodo supraclavicular esquerdo palpável. Hb 9,1 microcítica. EDA: lesão ulcerada infiltrativa em antro; biópsia: adenocarcinoma; urease positiva.","blocos":[{"t":"Diagnóstico","q":"Qual o diagnóstico e o que indica gravidade?","r":["Dispepsia com sinais de alarme: adenocarcinoma gástrico.","Provável doença avançada: linfonodo de Virchow.","Anemia ferropriva e H. pylori."],"e":"Perda de peso, idade ≥ 60, anemia e história familiar são sinais de alarme que obrigam a EDA. O linfonodo supraclavicular esquerdo é o nódulo de Virchow."},{"t":"Conduta","q":"Qual a conduta?","r":["Estadiamento: TC de tórax, abdome e pelve (± ecoendoscopia, laparoscopia); biópsia do linfonodo.","Encaminhar à oncologia e cirurgia oncológica (localizada: quimio perioperatória + gastrectomia com linfadenectomia D2; metastática: paliação sistêmica).","Suporte nutricional e reposição de ferro.","Erradicar o H. pylori e testar parentes de 1º grau."],"e":"Comunicar o diagnóstico com o protocolo SPIKES."}]},{"id":"hda-aine","area":"Adulto","tema":"Hemorragias digestivas","titulo":"Melena em usuário de AINE","caso":"Homem, 62 anos, melena há 2 dias e hoje vômito em “borra de café”, tontura ao levantar. Usa AAS 100 mg (prevenção primária) e ibuprofeno por artrose. Sem hepatopatia. PA 96/60, FC 114; toque retal com melena. Hb 8,0, ureia 110, Cr 1,0. Glasgow-Blatchford alto. EDA: úlcera bulbar de 1,5 cm com vaso visível (Forrest IIa); urease positiva.","blocos":[{"t":"Primeiro passo","q":"O paciente está instável. O que você faz primeiro?","r":["ABCDE antes de tudo: monitor, O₂, 2 acessos calibrosos, cristaloide, tipagem.","Perguntar AINE, anticoagulante, álcool e hepatopatia; toque retal.","Transfundir se Hb < 7 (alvo restritivo)."],"e":"Taquicardia e hipotensão mostram instabilidade hemodinâmica: ressuscitar antes de investigar."},{"t":"Diagnóstico","q":"Qual o diagnóstico?","r":["HDA não varicosa por úlcera duodenal Forrest IIa (alto risco de ressangramento).","Associada a AINE/AAS e H. pylori, com instabilidade hemodinâmica."],"e":"Ureia alta com creatinina normal é pista de sangramento digestivo alto."},{"t":"Conduta","q":"Qual a conduta?","r":["IBP IV + eritromicina antes da EDA; EDA em menos de 24 h com adrenalina + clipe.","IBP em alta dose por 72 h, depois VO.","Suspender ibuprofeno e AAS (prevenção primária).","Erradicar H. pylori (quádrupla com bismuto) com controle de cura.","Ressangrou → nova EDA → embolização."],"e":"Não usar ácido tranexâmico."}]},{"id":"hda-varizes","area":"Adulto","tema":"Hemorragias digestivas","titulo":"Hematêmese volumosa em cirrótica","caso":"Mulher, 54 anos, etilista, hematêmese volumosa de sangue vivo há 1 h, sonolenta e confusa. Ictérica, ascite, circulação colateral, aranhas vasculares. PA 80/50, FC 128. Hb 6,8, plaquetas 62 mil, INR 2,0, bilirrubina 4, albumina 2,4 → Child-Pugh C (12). EDA: varizes esofágicas de grosso calibre com sangramento ativo.","blocos":[{"t":"Diagnóstico","q":"Qual o diagnóstico?","r":["HDA varicosa por hipertensão portal (cirrose alcoólica Child C).","Choque hemorrágico e encefalopatia hepática."],"e":"Estigmas de hepatopatia + hematêmese de sangue vivo apontam para varizes."},{"t":"Estabilização","q":"O que você faz antes da EDA?","r":["Intubar antes da EDA (proteção de via aérea).","2 acessos, volume cauteloso, transfusão com alvo de Hb 7–8.","Terlipressina 2 mg IV 4/4 h (2–5 dias), ceftriaxona 1 g/dia, IBP até a EDA."],"e":"Na cirrose, o trio vasoativo + antibiótico + ligadura é essencial. Excesso de volume piora a hipertensão portal."},{"t":"Tratamento definitivo e seguimento","q":"E depois?","r":["EDA em menos de 12 h com ligadura elástica.","TIPS preemptivo em até 72 h (Child C < 14).","Lactulose; suspender betabloqueador e diurético na fase aguda.","Depois: carvedilol + ligaduras seriadas, abstinência alcoólica, avaliar transplante."],"e":"A encefalopatia hepática é tratada com lactulose."}]},{"id":"uro-colica","area":"Adulto","tema":"Urolitíase e rins","titulo":"Cólica renal não complicada","caso":"Homem, 34 anos, dor lombar esquerda súbita 10/10 irradiando para o testículo, vômitos, inquieto, afebril, Giordano + à esquerda. EAS: hematúria; Cr 0,9. TC: cálculo de 6 mm no ureter distal esquerdo, hidronefrose leve.","blocos":[{"t":"Diagnóstico","q":"Qual o diagnóstico?","r":["Cólica nefrética por litíase ureteral não complicada (afebril, creatinina normal, 6 mm, hidronefrose leve)."],"e":"A inquietação (paciente não acha posição) é típica da cólica, ao contrário da peritonite, em que o paciente fica imóvel."},{"t":"Conduta","q":"Qual o tratamento e a alta?","r":["AINE IM/IV + dipirona + metoclopramida.","Alta com AINE VO + tansulosina e peneirar a urina.","Urologia em 2–4 semanas.","Sem eliminação em 4–6 semanas → ureteroscopia (URS)."],"e":"Orientar sinais de retorno: febre, dor incontrolável, vômitos persistentes, anúria."}]},{"id":"uro-sepse","area":"Adulto","tema":"Urolitíase e rins","titulo":"Febre, hipotensão e cálculo obstrutivo","caso":"Mulher, 46 anos, diabética, dor lombar direita há 2 dias, febre 39 °C e calafrios. PA 85/50, FC 120. Leucócitos 19.800, lactato 3,5, Cr 1,8, nitrito +, β-hCG negativo. TC: cálculo de 8 mm no ureter proximal direito, hidronefrose moderada.","blocos":[{"t":"Diagnóstico","q":"Qual o diagnóstico?","r":["Pielonefrite obstrutiva com sepse.","Cálculo obstrutivo + infecção = emergência urológica."],"e":"Hipotensão, lactato elevado e leucocitose indicam sepse com disfunção de órgão (LRA, Cr 1,8)."},{"t":"Conduta","q":"Qual a conduta, em ordem?","r":["ABCDE; cristaloide 30 mL/kg.","Hemoculturas + urocultura e depois antibiótico (ceftriaxona 2 g ou piperacilina-tazobactam).","Descompressão urgente da via urinária.","Noradrenalina se PAM < 65.","Analgesia sem AINE (LRA).","Sem terapia expulsiva; URS depois que a infecção estiver controlada."],"e":"Obstrução + infecção = descomprimir já (cateter duplo J ou nefrostomia). Antibiótico sozinho não resolve."}]},{"id":"pros-nodulo","area":"Adulto","tema":"Próstata","titulo":"Nódulo no toque em homem assintomático","caso":"Homem, 62 anos, negro, pai teve câncer de próstata. Assintomático; após conversa sobre riscos e benefícios, quis avaliar. Toque: próstata de cerca de 30 g, fibroelástica, com nódulo endurecido de 1 cm no lobo direito, sulco preservado, móvel. PSA 6,8 (livre/total 12%; densidade 0,23). RM: lesão PI-RADS 4 na zona periférica direita. Biópsia transperineal: adenocarcinoma Gleason 3+4 = 7 (ISUP GG2) em 3 fragmentos; cT2a.","blocos":[{"t":"Toque retal","q":"Como você faz o exame e o que descreve?","r":["Consentimento, privacidade, acompanhante; luvas e lubrificante.","Introdução gentil.","Descrever tamanho, consistência, superfície, sulco, mobilidade e nódulo.","Olhar a luva."],"e":"Roteiro de fala: “vou fazer o exame do toque retal; pode haver desconforto, mas não deve doer. Posso fazer?”. Nódulo no toque = investigar mesmo com PSA normal."},{"t":"Diagnóstico","q":"Qual o diagnóstico?","r":["Adenocarcinoma de próstata localizado, risco intermediário (favorável)."],"e":"A RM antes da biópsia orienta o alvo. Gleason 3+4 = ISUP grau grupo 2."},{"t":"Conduta","q":"Como comunicar e qual a conduta?","r":["Comunicar com o protocolo SPIKES.","Decisão compartilhada com urologia e radio-oncologia: prostatectomia radical ou radioterapia (± bloqueio hormonal curto).","Vigilância ativa só se GG2 com pouco padrão 4.","Explicar riscos (incontinência, disfunção erétil).","Orientar irmãos e filhos a avaliar a partir dos 45 anos; considerar teste genético."],"e":"A história familiar de câncer de próstata antecipa o rastreamento dos parentes."}]},{"id":"pros-metastase","area":"Adulto","tema":"Próstata","titulo":"Dor óssea e fraqueza nas pernas","caso":"Homem, 74 anos, dor lombar e no quadril há 3 meses, perda de 6 kg; há 2 dias, fraqueza nas pernas, parestesia e retenção urinária. Força grau 3 em MMII, nível sensitivo em T10. Toque: próstata pétrea, irregular, fixa, sulco apagado. PSA 286. RM de coluna: metástases com compressão medular em T10.","blocos":[{"t":"Diagnóstico","q":"Qual o diagnóstico?","r":["Câncer de próstata metastático (ósseo) com compressão medular.","Emergência oncológica."],"e":"Próstata pétrea e fixa, PSA muito alto e dor óssea indicam doença avançada. Fraqueza + retenção + nível sensitivo = compressão medular."},{"t":"Conduta","q":"O que fazer agora?","r":["Dexametasona IV em dose alta já (ex.: 10–16 mg), repouso e analgesia.","Sondagem vesical.","Avaliação urgente de neurocirurgia e radioterapia (descompressão).","Bloqueio hormonal imediato, de preferência antagonista de LHRH (degarelix) ou orquiectomia, para evitar o flare do agonista.","Confirmar com biópsia.","Depois: bloqueio + inibidor da via androgênica (± docetaxel), proteção óssea, cuidados paliativos."],"e":"O agonista de LHRH pode causar flare transitório de testosterona, perigoso na compressão medular."}]},{"id":"mama-fibroadenoma","area":"Adulto","tema":"Mama","titulo":"Jovem de 22 anos com nódulo móvel","caso":"Mulher, 22 anos, nódulo na mama esquerda há 4 meses, indolor, sem crescimento; sem história familiar. Nódulo de 2 cm no QSE da mama esquerda, ovalado, fibroelástico, limites bem definidos, liso, muito móvel, indolor; pele e mamilo normais; axilas livres. USG: nódulo sólido oval, circunscrito, paralelo à pele, BI-RADS 3.","blocos":[{"t":"Exame","q":"Como você examina e descreve?","r":["Consentimento e acompanhante; exposição respeitosa.","Inspeção estática e dinâmica; axila, supra e infraclavicular.","Palpação deitada, mão sob a cabeça, polpas dos dedos, 3 pressões, padrão sistemático, incluindo a cauda axilar; as duas mamas.","Descrever o nódulo completo: localização, tamanho, forma, bordas, superfície, consistência, mobilidade, dor, pele e mamilo."],"e":"A descrição completa do nódulo é o que o examinador pontua."},{"t":"Diagnóstico","q":"Qual o diagnóstico?","r":["Nódulo mamário de características benignas: provável fibroadenoma (BI-RADS 3)."],"e":"Móvel, liso, bem delimitado e oval, em mulher jovem: fibroadenoma. BI-RADS 3 = provavelmente benigno."},{"t":"Conduta","q":"Qual a conduta?","r":["Tranquilizar e explicar.","Mamografia não é necessária (< 30 anos).","USG de controle em 6 meses (seguir 1–2 anos).","Biópsia por agulha grossa se crescer (> 20% em 6 meses), > 3 cm, mudar de aspecto ou por desejo da paciente.","Exérese se grande, sintomático ou suspeita de filoides."],"e":"Em mulheres jovens o exame de imagem de escolha é a USG."}]},{"id":"mama-ca","area":"Adulto","tema":"Mama","titulo":"Nódulo endurecido com retração de pele","caso":"Mulher, 58 anos, menopausa aos 54, usa terapia hormonal; mãe com câncer de mama aos 62. Nódulo há 2 meses. Retração da pele no QSE da mama direita, acentuada com as mãos na cintura. Nódulo de 3 cm, endurecido, irregular, mal delimitado, aderido, indolor; linfonodo axilar direito de 1,5 cm, endurecido, móvel. Mamografia: massa espiculada, BI-RADS 5; USG: linfonodo com cortical espessada.","blocos":[{"t":"Achados","q":"Quais achados sugerem malignidade?","r":["Retração de pele (inspeção dinâmica).","Nódulo endurecido, irregular, mal delimitado e aderido.","Linfonodo axilar endurecido.","Massa espiculada na mamografia (BI-RADS 5)."],"e":"Inspeção dinâmica (mãos na cintura) acentua retrações pela tração dos ligamentos."},{"t":"Diagnóstico","q":"Qual o diagnóstico?","r":["Nódulo mamário altamente suspeito de carcinoma (BI-RADS 5), com provável comprometimento axilar (cT2 N1)."],"e":"BI-RADS 5 tem probabilidade de malignidade acima de 95%."},{"t":"Conduta","q":"Qual a conduta?","r":["Biópsia por agulha grossa guiada por USG do nódulo (histologia + imuno-histoquímica: RE, RP, HER2, Ki-67) e do linfonodo.","Suspender a terapia hormonal.","Encaminhar com prioridade à mastologia/oncologia (prazos de 30 e 60 dias).","Estadiamento conforme o resultado.","Comunicar com SPIKES."],"e":"A terapia hormonal é suspensa pelo risco de estimular o tumor."}]},{"id":"ist-ulcera","area":"Adulto","tema":"Úlcera genital e corrimento","titulo":"Úlcera indolor no pênis","caso":"Homem, 24 anos, ferida no pênis há 10 dias, indolor; relação sem preservativo com parceira nova há 3 semanas. Úlcera única de 1 cm no sulco balanoprepucial, base limpa e endurecida, bordas elevadas; linfonodos inguinais bilaterais, indolores, móveis. Sem vesículas. Teste rápido treponêmico reagente; VDRL 1:32; teste rápido de HIV não reagente.","blocos":[{"t":"Abordagem","q":"Como você conversa e examina?","r":["Comunicação sem julgamento e sigilo: “é tudo sigiloso e ajuda no tratamento”.","Consentimento e acompanhante.","Inspeção, palpar a base da úlcera e linfonodos inguinais."],"e":"A base endurecida e a ausência de dor distinguem o cancro duro do cancro mole e do herpes (vesículas dolorosas)."},{"t":"Diagnóstico","q":"Qual o diagnóstico?","r":["Sífilis primária (cancro duro)."],"e":"Teste treponêmico reagente com VDRL 1:32 confirma."},{"t":"Conduta","q":"Qual o tratamento e o seguimento?","r":["Penicilina benzatina 2,4 milhões UI IM, dose única (1,2 milhão em cada glúteo); avisar sobre a reação de Jarisch-Herxheimer.","Notificar.","Convocar e tratar a parceria (exposição nos últimos 90 dias: tratar mesmo com teste negativo).","VDRL trimestral (esperar queda de 2 diluições).","Testar hepatites B e C e repetir o HIV após a janela; preservativo, vacina HPV/hepatite B e oferecer PrEP.","Sem teste disponível: penicilina + azitromicina (sindrômico)."],"e":"Nas IST, tratar a parceria é parte do tratamento."}]},{"id":"ist-corrimento","area":"Adulto","tema":"Úlcera genital e corrimento","titulo":"Corrimento esverdeado e disúria","caso":"Mulher, 27 anos, corrimento amarelo-esverdeado, com mau cheiro, prurido, disúria e dispareunia há 1 semana. Parceiro novo há 2 meses, preservativo irregular. DUM há 10 dias. Especular: conteúdo abundante, bolhoso, colo em framboesa, sem mucopus. pH 6,0; aminas fracamente +; a fresco: protozoários flagelados móveis. Sem dor à mobilização do colo.","blocos":[{"t":"Exame","q":"Que etapas e achados do exame especular?","r":["Especular com técnica, pH medido na parede lateral e teste das aminas.","Conteúdo abundante e bolhoso, colo em framboesa.","A fresco: protozoários flagelados móveis.","Sem dor à mobilização do colo (afasta doença inflamatória pélvica)."],"e":"Diferencie: candidíase (branco grumoso, pH normal), vaginose bacteriana (cinza, aminas +) e tricomoníase (verde, bolhoso, pH alto)."},{"t":"Diagnóstico e tratamento","q":"Qual o diagnóstico e o tratamento?","r":["Tricomoníase (Trichomonas vaginalis): IST.","Metronidazol 2 g VO dose única (ou 500 mg 12/12 h por 7 dias); sem álcool até 24 h depois.","Tratar o parceiro com o mesmo esquema; abstinência até ambos terminarem."],"e":"É um dos poucos corrimentos em que o parceiro deve ser tratado."},{"t":"Seguimento","q":"Que exames e orientações completam o atendimento?","r":["Testar HIV, sífilis, hepatites B e C e clamídia/gonococo.","Preservativo, vacinas e citologia em dia.","Retorno se persistir."],"e":"Uma IST faz pensar nas outras."}]},{"id":"lra-prerrenal","area":"Adulto","tema":"LRA e DRC","titulo":"Idosa com diarreia, oligúria e K 6,4","caso":"Mulher, 78 anos, HAS em losartana + hidroclorotiazida; diarreia e vômitos há 3 dias, tomou ibuprofeno; urina pouco, tontura. PA 90/60, FC 110, mucosas secas, TEC 4 s. Cr 3,2 (basal 1,0), ureia 160, K 6,4, pH 7,28, HCO₃ 15. FENa 0,4%, Na urinário 12; EAS com cilindros hialinos. ECG: T apiculada. USG: rins normais, sem hidronefrose.","blocos":[{"t":"Diagnóstico","q":"Qual o diagnóstico?","r":["LRA KDIGO estágio 3, pré-renal.","Hipovolemia por gastroenterite + “tripla tacada” (BRA, diurético, AINE).","Hipercalemia com alteração no ECG e acidose metabólica."],"e":"Aguda × crônica: creatinina basal normal e USG sem rins reduzidos. FENa < 1% e cilindros hialinos indicam causa pré-renal."},{"t":"Hipercalemia","q":"Qual a conduta imediata?","r":["Monitor.","Gluconato de cálcio 10% 10 mL IV (proteção da membrana).","Insulina regular 10 UI + glicose; salbutamol nebulizado."],"e":"Com alteração no ECG, o cálcio vem primeiro: ele protege o coração, mas não baixa o potássio."},{"t":"Causa e seguimento","q":"E depois?","r":["Suspender losartana, hidroclorotiazida e ibuprofeno.","Ringer lactato 500 mL em bolus, reavaliando a volemia.","Balanço hídrico, diurese, K e Cr seriados.","Diálise se K, acidose ou oligúria refratários.","Reavaliar a função renal em 3 meses e orientar “dias de doença”."],"e":"“Dias de doença”: suspender temporariamente IECA/BRA, diurético, AINE e metformina durante vômitos e diarreia."}]},{"id":"drc-diabetico","area":"Adulto","tema":"LRA e DRC","titulo":"Diabético com albuminúria","caso":"Homem, 58 anos, DM2 há 15 anos e HAS. Usa metformina 850 mg 3×/dia, glibenclamida e enalapril 10 mg. Assintomático. PA 152/94, IMC 31, edema +/4+, retinopatia diabética. Cr 1,9 → TFG 39 (estável há 1 ano), RAC 620 mg/g (repetida: 580), Hb 11,2, K 4,9, HCO₃ 21, HbA1c 8,6%. USG: rins de 10 cm, hiperecogênicos.","blocos":[{"t":"Diagnóstico","q":"Qual o diagnóstico e o estadiamento?","r":["DRC G3b A3 por doença renal do diabetes.","HAS não controlada e anemia.","Risco muito alto."],"e":"DRC = alteração por mais de 3 meses (TFG estável há 1 ano). G3b = TFG 30–44; A3 = albuminúria > 300 mg/g. Retinopatia sustenta a causa diabética."},{"t":"Tratamento","q":"Qual o tratamento?","r":["Enalapril até a dose máxima (20 mg 12/12 h); checar Cr/K em 2–4 semanas.","Dapagliflozina 10 mg; considerar finerenona se a albuminúria persistir.","Metformina no máximo 1 g/dia; trocar a glibenclamida (ex.: agonista de GLP-1).","Meta de PA, estatina, sódio < 2 g e proteína 0,8 g/kg."],"e":"IECA/BRA + iSGLT2 são a base para frear a progressão. A glibenclamida acumula na DRC e dá hipoglicemia."},{"t":"Cuidados e encaminhamento","q":"O que mais?","r":["Investigar a anemia (ferro).","Evitar AINE e contraste.","Vacinar.","Encaminhar à nefrologia (A3)."],"e":"Albuminúria A3 é critério de encaminhamento."}]},{"id":"rge-fisiologico","area":"Pediatria","tema":"Refluxo (RGE e DRGE)","titulo":"“Meu bebê golfa depois de todas as mamadas”","caso":"Lactente de 3 meses, aleitamento materno exclusivo, regurgita 5–6 vezes ao dia desde as 3 semanas de vida, logo após mamar, sem esforço, conteúdo lácteo. Sorri, mama e dorme bem, sem choro excessivo. Evacuações e diurese normais, sem sangue. Ganho de 30 g/dia, peso no P50. Exame normal; fontanela normotensa; pega adequada.","blocos":[{"t":"Anamnese","q":"O que você pergunta?","r":["Se golfa sem fazer força ou vomita com esforço.","Se sai algo verde ou com sangue.","Como está o ganho de peso (e colocar peso e PC na curva).","Alimentação: volume, preparo, aleitamento, pega."],"e":"Vômito bilioso, em jato, com sangue, febre ou perda de peso são sinais de alarme."},{"t":"Diagnóstico","q":"Qual o diagnóstico?","r":["RGE fisiológico (regurgitação do lactente, Roma IV): “regurgitador feliz”.","Sem DRGE e sem sinais de alarme."],"e":"RGE é o refluxo sem sintomas incômodos; DRGE é quando causa sintomas incômodos ou complicações (baixo ganho de peso, esofagite)."},{"t":"Conduta","q":"Qual a conduta e as orientações?","r":["Tranquilizar a mãe: é comum e melhora até 1–2 anos.","Não pedir exames nem prescrever IBP.","Manter o aleitamento materno exclusivo.","Manter o bebê em pé por 20–30 min após mamar, arrotar, evitar apertar a barriga.","Dormir de barriga para cima, sem elevar o berço.","Orientar sinais de alarme (vômito verde ou em jato, sangue, febre, perda de peso, recusa) e seguir o crescimento na puericultura."],"e":"IBP em lactente sem DRGE não ajuda e tem riscos."}]},{"id":"drge-aplv","area":"Pediatria","tema":"Refluxo (RGE e DRGE)","titulo":"Regurgitação, choro e baixo ganho de peso","caso":"Lactente de 5 meses, desmamado aos 2 meses, em fórmula de leite de vaca (preparo correto). Regurgitações frequentes, choro intenso e arqueamento durante as mamadas, recusa alimentar. Eczema em face; fezes com estrias de sangue às vezes. Peso caiu do P50 para o P10. Pai com rinite alérgica. Sem febre, vômito bilioso ou em jato; abdome normal.","blocos":[{"t":"Diagnóstico","q":"Qual o diagnóstico?","r":["DRGE do lactente (sintomas incômodos + baixo ganho de peso).","Forte suspeita de alergia à proteína do leite de vaca (eczema, sangue nas fezes, atopia familiar)."],"e":"Eczema + sangue nas fezes + atopia familiar + sintomas de refluxo sugerem APLV como causa."},{"t":"Conduta","q":"Qual a conduta?","r":["Trocar para fórmula extensamente hidrolisada por 2–4 semanas (aminoácidos se não houver resposta ou quadro grave).","Não iniciar IBP de primeira.","Reavaliar o peso em 2 semanas.","Melhorou → manter a exclusão e programar o teste de provocação.","Sem melhora → IBP por 4–8 semanas e gastropediatria (EDA).","Posição supina para dormir; sinais de alarme; apoio nutricional."],"e":"Na DRGE do lactente, o teste de exclusão do leite de vaca vem antes do IBP."}]},{"id":"itu-lactente","area":"Pediatria","tema":"Urologia pediátrica","titulo":"Lactente com febre sem foco","caso":"Menina de 9 meses, 9 kg, febre de 39,5 °C há 2 dias, irritada, 2 vômitos, aceita leite; urina com cheiro forte. Sem tosse, coriza ou diarreia. Bom estado geral entre os picos, hidratada; orofaringe, otoscopia e ausculta normais; abdome sem massas ou globo; genitália normal, sem sinéquia; coluna normal. Urina por sondagem: nitrito +, esterase +, 50 leucócitos/campo, bacilos gram-negativos; urocultura colhida.","blocos":[{"t":"Diagnóstico","q":"Qual o diagnóstico?","r":["ITU febril, provável pielonefrite aguda (febre sem foco e urina alterada colhida por sondagem).","Sem critérios de internação."],"e":"Pense em ITU na febre sem foco do lactente. A coleta correta é por sondagem; o saco coletor só serve para excluir."},{"t":"Conduta","q":"Qual o tratamento e o seguimento?","r":["Ambulatorial: cefuroxima 135 mg 12/12 h (30 mg/kg/dia) ou amoxicilina-clavulanato, por 7–10 dias; antitérmico e hidratação.","Reavaliar em 48–72 h com a urocultura (ajustar pelo antibiograma).","USG de rins e vias urinárias.","Retorno se piorar, vomitar tudo ou ficar prostrada.","Uretrocistografia se USG alterada ou recorrência."],"e":"A urocultura deve ser colhida antes do antibiótico."}]},{"id":"itu-disfuncao","area":"Pediatria","tema":"Urologia pediátrica","titulo":"Menina que “não chega a tempo ao banheiro”","caso":"Menina de 6 anos, há 3 dias com ardor ao urinar, polaciúria e urgência, sem febre. Há meses perde xixi durante o dia, “segura” até o último minuto (cruza as pernas) e evacua a cada 4–5 dias fezes duras. 2 episódios semelhantes no último ano. Afebril, Giordano negativo, fecaloma palpável em FIE; vulva com leve hiperemia, sem corrimento ou sinéquia; coluna normal. Jato médio: nitrito +, leucocitúria; urocultura colhida.","blocos":[{"t":"Anamnese e exame","q":"O que você pergunta e examina?","r":["Hábito miccional e intestinal.","Consentimento e acompanhante (mãe) no exame genital.","Procurar sinéquia, vulvovaginite, globo vesical, rins e coluna."],"e":"Segurar a urina e a constipação são os dois pilares da disfunção vesical e intestinal."},{"t":"Diagnóstico","q":"Qual o diagnóstico?","r":["Cistite (ITU baixa) recorrente associada a disfunção vesical e intestinal (micção adiada + constipação)."],"e":"Afebril, sem dor no flanco e Giordano negativo: ITU baixa."},{"t":"Conduta","q":"Qual a conduta?","r":["Nitrofurantoína 5–7 mg/kg/dia 6/6 h (ou cefalexina) por 3–5 dias, ajustando pela cultura.","Tratar a constipação (desimpactação e PEG de manutenção).","Uroterapia: urinar a cada 2–3 h, apoio para os pés, mais água, não segurar; diário miccional; higiene da frente para trás.","USG (resíduo pós-miccional, rins).","Encaminhar à nefro/urologia se persistir."],"e":"Sem tratar a constipação, a ITU volta."}]},{"id":"constip-funcional","area":"Pediatria","tema":"Constipação e diarreia","titulo":"“Ele está com diarreia na cueca”","caso":"Menino de 5 anos, 20 kg. Há 8 meses, desde que entrou na escola, evacua 2 vezes por semana fezes duras e grossas que entopem o vaso, com dor e às vezes sangue no papel. Esconde-se e cruza as pernas quando tem vontade. Suja a cueca 3 vezes por semana (a mãe acha que é diarreia). Mecônio nas primeiras 24 h; crescimento no P50. Abdome levemente distendido, massa endurecida e moldável em hipogástrio e FIE, indolor; fissura anal às 6 h e sujidade fecal; coluna e reflexos de MMII normais.","blocos":[{"t":"Diagnóstico","q":"Qual o diagnóstico?","r":["Constipação funcional (Roma IV, ≥ 4 anos: ≥ 2 critérios) com impactação fecal, incontinência por transbordamento e fissura anal.","Sem sinais de alarme (mecônio nas primeiras 24 h, crescimento normal, exame neurológico normal)."],"e":"O “diarreia na cueca” é escape fecal por transbordamento."},{"t":"Tratamento","q":"Como você desimpacta e mantém?","r":["Explicar o ciclo: o escape não é diarreia nem “preguiça”.","Desimpactação: PEG 20–30 g/dia (1–1,5 g/kg) por 3–6 dias.","Manutenção: PEG cerca de 8–16 g/dia (0,4–0,8 g/kg), ajustando, por 2 meses ou mais."],"e":"Desimpactar antes de manter. Não usar óleo mineral em menores de 1 ano."},{"t":"Medidas de apoio","q":"Que orientações comportamentais?","r":["Sentar no vaso após as refeições com apoio para os pés.","Calendário de recompensas e diário de fezes; banho de assento.","Retorno em 2 semanas."],"e":"Educação sem culpa melhora a adesão."}]},{"id":"constip-hirsch","area":"Pediatria","tema":"Constipação e diarreia","titulo":"Constipação desde o nascimento","caso":"Lactente de 3 meses, eliminou mecônio com 72 h. Desde então evacua só com estímulo, abdome muito distendido, vômitos ocasionais, baixo ganho de peso (P3). Distensão com alças palpáveis; toque retal: ampola vazia e, ao retirar o dedo, saída explosiva de fezes líquidas e gases. Sem febre.","blocos":[{"t":"Diagnóstico","q":"É constipação funcional? Qual a suspeita?","r":["Não é funcional: suspeita de doença de Hirschsprung (aganglionose colônica).","Sinais de alarme: mecônio tardio, início ao nascer, distensão, baixo ganho de peso, sinal da explosão."],"e":"Mecônio depois de 48 h é sinal de alarme clássico."},{"t":"Conduta","q":"Qual a conduta?","r":["Encaminhar à cirurgia pediátrica.","Enema opaco (zona de transição), manometria anorretal (sem reflexo inibitório retoanal) e biópsia retal por sucção (padrão-ouro: sem células ganglionares).","Irrigações retais com soro enquanto isso.","Orientar sinais de enterocolite (febre, distensão, diarreia fétida) como emergência.","Tratamento definitivo: cirurgia de abaixamento."],"e":"Enterocolite é a complicação grave e pode ser fatal."}]},{"id":"glom-nefritica","area":"Pediatria","tema":"Glomerulopatias","titulo":"“O xixi dele está cor de Coca-Cola”","caso":"Menino de 7 anos, 24 kg, há 2 dias com urina “cor de Coca-Cola”, olhos inchados pela manhã, urinando pouco, cefaleia. Feridas com crostas nas pernas há 4 semanas. PA 132/88 (acima do p99 + 5 mmHg), edema palpebral e de MMII (2+/4+), cicatrizes de impetigo; pulmões limpos. EAS: hemácias incontáveis, dismórficas, cilindros hemáticos, proteína 1+. Cr 1,1; C3 baixo, C4 normal; anti-DNase B elevado.","blocos":[{"t":"Anamnese","q":"O que você pergunta?","r":["Cor da urina e se tem espuma; se está urinando menos.","Dor de garganta ou feridas na pele nas últimas semanas (e o intervalo)."],"e":"Impetigo prévio com 3–6 semanas de intervalo sugere glomerulonefrite pós-estreptocócica."},{"t":"Diagnóstico","q":"Qual o diagnóstico?","r":["Síndrome nefrítica por glomerulonefrite pós-estreptocócica (pós-impetigo).","Com hipertensão (estágio 2), oligúria e IRA leve."],"e":"Hematúria glomerular (hemácias dismórficas, cilindros) + edema + hipertensão + C3 baixo."},{"t":"Conduta","q":"Qual o tratamento?","r":["Internar.","Restrição de sódio e de líquidos (insensíveis + diurese); furosemida 1–2 mg/kg; anlodipino se a PA não controlar.","Monitorar PA, peso, diurese, creatinina e K.","Penicilina benzatina 900.000–1.200.000 UI IM (erradicação).","C3 em 6–8 semanas (se baixo → nefrologia/biópsia)."],"e":"É um tratamento de suporte: a doença costuma ser autolimitada."}]},{"id":"glom-nefrotica","area":"Pediatria","tema":"Glomerulopatias","titulo":"“Ela acordou com os olhos inchados”","caso":"Menina de 4 anos, 16 kg, 100 cm (SC ≈ 0,67 m²), há 10 dias com edema palpebral matinal que se espalhou para pernas e barriga; urina espumosa, cor normal. PA 98/60 (normal), edema generalizado com cacifo, ascite leve, sem lesões de pele. EAS: proteína 4+, sem hematúria significativa. Proteína/creatinina urinária 7 mg/mg; albumina 1,7 g/dL; colesterol 390 mg/dL; creatinina 0,3; C3 normal.","blocos":[{"t":"Diagnóstico","q":"Qual o diagnóstico?","r":["Síndrome nefrótica idiopática (provável doença de lesão mínima).","Idade típica, PA, função renal e C3 normais, sem hematúria."],"e":"Nefrótica = proteinúria maciça, hipoalbuminemia, edema e dislipidemia. A diferença da nefrítica é a ausência de hematúria e hipertensão."},{"t":"Conduta","q":"Qual o tratamento?","r":["Prednisolona 40 mg/dia (60 mg/m²) por 4 semanas, depois 27 mg em dias alternados (40 mg/m²) por 4 semanas.","Dieta hipossódica, proteína normal; diurético e albumina só se edema grave/sintomático.","Vacina pneumocócica.","Orientar sinais de peritonite (febre + dor abdominal), trombose e hipovolemia; fita urinária em casa.","Biópsia só se corticorresistente."],"e":"A dose do corticoide é calculada por m² de superfície corporal."}]},{"id":"gastrosquise","area":"Pediatria","tema":"Abdome agudo","titulo":"Alças expostas ao nascer","caso":"RN a termo, mãe de 18 anos. Ao nascer, alças intestinais exteriorizadas à direita do umbigo, sem membrana recobrindo, edemaciadas e com fibrina; cordão umbilical inserido normalmente. FC 150, chorando, T 36,2 °C.","blocos":[{"t":"Diagnóstico","q":"Qual o diagnóstico e o risco?","r":["Gastrosquise: defeito de parede paraumbilical direito, sem saco.","Risco de hipotermia, perda hídrica, infecção e sofrimento das alças."],"e":"Na onfalocele há saco recobrindo e o cordão se insere nele; na gastrosquise não há saco."},{"t":"Conduta na sala de parto","q":"O que fazer?","r":["Não reduzir as alças.","Cobrir com plástico/filme estéril transparente (ou bolsa), alças centralizadas e sem torção; decúbito lateral direito; berço aquecido.","Sonda orogástrica aberta; acesso venoso com hidratação generosa; glicemia; antibiótico de amplo espectro.","Cirurgia pediátrica (fechamento primário ou silo); comunicar a família."],"e":"Perda de calor e de líquido pelas alças expostas é o maior risco imediato."}]},{"id":"invaginacao","area":"Pediatria","tema":"Abdome agudo","titulo":"Choro com crises e fezes com sangue","caso":"Lactente de 8 meses, saudável, há 10 h com crises de choro intenso, encolhe as pernas, fica pálido; entre as crises fica quieto e sonolento. 3 vômitos (o último esverdeado). Agora evacuou fezes com muco e sangue (“geleia de framboesa”). FC 168, TEC 3 s, mucosas secas; abdome pouco distendido, massa alongada em hipocôndrio direito, fossa ilíaca direita vazia; sem defesa.","blocos":[{"t":"Exame","q":"Como você examina uma criança assim?","r":["Mãos aquecidas, criança no colo da mãe, olhando o rosto dela.","Inspeção, ausculta, percussão e palpação, nessa ordem.","Descrever a massa (alongada, “em salsicha”, em hipocôndrio direito) e a fossa ilíaca direita vazia."],"e":"Vômito bilioso indica obstrução. Conhecer o normal: fígado até 2–3 cm, baço palpável no RN."},{"t":"Diagnóstico","q":"Qual o diagnóstico?","r":["Invaginação intestinal (ileocólica), com desidratação, sem sinais de perfuração ou peritonite."],"e":"Crises de choro com palidez, intervalos quietos, massa e fezes em geleia de framboesa."},{"t":"Conduta","q":"Qual a conduta?","r":["Jejum, acesso venoso e expansão (SF 0,9% 20 mL/kg), analgesia, SNG pelos vômitos biliosos.","USG (sinal do alvo) e avisar a cirurgia pediátrica.","Estável e sem peritonite: redução por enema (ar ou soro) guiada por imagem.","Falha, perfuração, peritonite ou choque: laparotomia.","Observar (recidiva em 24–48 h)."],"e":"Chamar o cirurgião pediátrico cedo."}]},{"id":"ict-abo","area":"Pediatria","tema":"Fígado e icterícia","titulo":"Icterícia no 2º dia de vida","caso":"RN de 39 semanas, 36 h de vida, aleitamento exclusivo. Icterícia notada com 20 h de vida, hoje até as coxas (Kramer 3–4). Mama bem, sem perda de peso excessiva; ativo, tônus normal. Mãe O Rh+; RN A Rh+, Coombs direto positivo. BT 15 mg/dL (BD 0,6), Hb 13,5, reticulócitos 9%; esfregaço com esferócitos.","blocos":[{"t":"Anamnese e exame","q":"O que você pergunta e como examina?","r":["Idade de início em horas; tipo sanguíneo e Rh da mãe e do RN; aleitamento e peso; cor das fezes e da urina.","Examinar em luz natural com digitopressão e citar Kramer.","Procurar hepatoesplenomegalia e sinais neurológicos."],"e":"Icterícia nas primeiras 24 h é sempre patológica até prova em contrário."},{"t":"Diagnóstico","q":"Qual o diagnóstico?","r":["Hiperbilirrubinemia indireta patológica por doença hemolítica por incompatibilidade ABO.","Início antes de 24 h, Coombs +, reticulocitose.","Acima do limiar de fototerapia e sem encefalopatia."],"e":"Mãe O e RN A é a combinação clássica da incompatibilidade ABO."},{"t":"Conduta","q":"Qual a conduta?","r":["Fototerapia intensiva (despido, olhos protegidos); manter o aleitamento 8–12 vezes ao dia; monitorar hidratação e temperatura; BT de controle em 4–6 h.","BT subindo apesar da fototerapia ou ≤ 2 mg/dL do limiar de exsanguineotransfusão: UTI, imunoglobulina IV e preparar exsanguineotransfusão.","Vigiar sinais de encefalopatia.","Após a alta: controle de BT (rebote) e de Hb (anemia tardia)."],"e":"O objetivo é prevenir a encefalopatia bilirrubínica (kernicterus)."}]},{"id":"ict-colestase","area":"Pediatria","tema":"Fígado e icterícia","titulo":"Icterícia que não passa","caso":"Lactente de 5 semanas, a termo, aleitamento exclusivo, ganhando peso. A mãe diz que continua amarelo; urina escura que mancha a fralda e fezes esbranquiçadas (cartão: cor 2). Icterícia com tom esverdeado, fígado a 4 cm do RCD, endurecido, baço palpável. BT 8,2 mg/dL, BD 5,6, GGT 680, TGO/TGP pouco elevadas, INR 1,4.","blocos":[{"t":"Diagnóstico","q":"Qual o diagnóstico?","r":["Colestase neonatal (BD elevada, colúria e acolia), com forte suspeita de atresia biliar.","Coagulopatia por deficiência de vitamina K."],"e":"Icterícia com mais de 14 dias ou fezes claras é colestase até prova em contrário. Não é icterícia do leite materno."},{"t":"Conduta","q":"Qual a conduta?","r":["Encaminhar com urgência à hepatologia/cirurgia pediátrica.","Vitamina K IV/IM.","USG de abdome em jejum, sorologias, alfa-1-antitripsina, TSH, urocultura; cintilografia, biópsia hepática e colangiografia.","Confirmada: portoenterostomia de Kasai o quanto antes (idealmente antes de 60 dias).","Manter a amamentação; vitaminas lipossolúveis; explicar à família a urgência."],"e":"A chance de sucesso do Kasai cai com a idade."}]},{"id":"diarr-planoA","area":"Pediatria","tema":"Constipação e diarreia","titulo":"Diarreia sem desidratação: orientar em casa","caso":"Lactente de 8 meses, 8 kg, diarreia aquosa há 2 dias (4–5 vezes ao dia), sem sangue, sem vômitos; mama no peito e come papinha. A família usa água de poço sem tratamento; vacina do rotavírus não feita. Alerta, olhos normais, bebe normalmente, prega volta rápido, pulso cheio, TEC 2 s, sem perda de peso.","blocos":[{"t":"Classificação","q":"Como você avalia e classifica a hidratação?","r":["Avaliar estado geral, olhos, sede (oferecer líquido), prega, pulso, TEC e pesar.","Sem sinais de desidratação: Plano A.","Fatores de risco: água não tratada e esquema vacinal incompleto."],"e":"Aplicar a regra dos 2 sinais (coluna B ou C)."},{"t":"Plano A","q":"O que você ensina à mãe?","r":["Preparar a SRO: 1 envelope em 1 L de água fervida e fria, válida por 24 h.","Oferecer 50–100 mL após cada evacuação, em colher ou copo.","Manter o aleitamento e a papinha.","Zinco 20 mg/dia por 10–14 dias."],"e":"Manter a alimentação durante a diarreia reduz a duração e o risco de desnutrição."},{"t":"Prevenção e retorno","q":"Que orientações finais?","r":["Tratar a água (ferver ou 2 gotas de hipoclorito por litro, 30 min); lavar as mãos.","Vacina do rotavírus: não pode mais (passou de 7 meses e 29 dias); atualizar as demais.","Retorno se piora, vômitos, sede intensa, sangue, febre, pouca urina ou sonolência."],"e":"A idade máxima para a 1ª dose do rotavírus é 3 meses e 15 dias; para a 2ª, 7 meses e 29 dias."}]},{"id":"diarr-planoC","area":"Pediatria","tema":"Constipação e diarreia","titulo":"Desidratação grave: calcular o Plano C","caso":"Criança de 2 anos, 12 kg, diarreia volumosa e vômitos há 2 dias. Sonolenta, olhos muito fundos, não consegue beber, prega muito lenta, pulso fino, TEC 6 s, extremidades frias; não urina há 10 h.","blocos":[{"t":"Classificação","q":"Qual a classificação e o plano?","r":["Diarreia aguda com desidratação grave: 2 ou mais sinais da coluna C (os com asterisco).","Plano C."],"e":"Aplicar a regra dos 2 sinais, sempre incluindo ao menos um dos sinais com asterisco."},{"t":"Expansão","q":"Calcule o Plano C.","r":["Acesso venoso (ou intraósseo), monitorizar, glicemia.","Maior de 1 ano: 30 mL/kg em 30 min = 360 mL de SF 0,9%; depois 70 mL/kg em 2 h 30 = 840 mL.","Reavaliar a cada etapa (repetir a 1ª se ainda grave)."],"e":"Menores de 1 ano recebem os mesmos volumes em 1 h e 5 h."},{"t":"Manutenção e alta","q":"E depois de hidratada?","r":["Manutenção 1.100 mL/dia (1.000 + 50 × 2) + reposição cerca de 600 mL/dia, com KCl após diurese.","Iniciar SRO quando conseguir beber; depois Plano A com zinco 20 mg/dia.","Eletrólitos; observar por 6 h ou mais."],"e":"A manutenção segue a regra de Holliday-Segar."}]},{"id":"diarr-planoB","area":"Pediatria","tema":"Constipação e diarreia","titulo":"Diarreia e vômitos no lactente","caso":"Criança de 18 meses, 11 kg (12 kg há 1 semana), diarreia aquosa há 3 dias, 6–7 vezes ao dia, sem sangue; 3 vômitos hoje; febre baixa; irmão da creche com o mesmo quadro. Vacina do rotavírus atrasada. Irritada, olhos fundos, bebe a água com avidez, prega desaparece lentamente, pulso rápido, TEC 3 s; abdome flácido.","blocos":[{"t":"Classificação","q":"Qual o diagnóstico e o plano?","r":["Diarreia aguda aquosa (provável viral) com desidratação.","2 ou mais sinais da coluna B; perda de cerca de 8% do peso.","Plano B."],"e":"Perda de 1 kg em 12 kg é cerca de 8%."},{"t":"Plano B","q":"Qual a conduta?","r":["SRO 50–100 mL/kg em 4–6 h (550–1.100 mL) na unidade, em pequenos volumes.","Ondansetrona 2 mg pelos vômitos; manter o aleitamento.","Reavaliar: hidratada → Plano A (SRO 100–200 mL após cada evacuação, alimentação habitual, zinco 20 mg/dia por 10–14 dias, sinais de retorno).","Sem antibiótico; atualizar vacinas e orientar lavagem das mãos."],"e":"Se não melhorar no Plano B, avance para o C."}]},{"id":"diarr-disenteria","area":"Pediatria","tema":"Constipação e diarreia","titulo":"Diarreia com sangue e febre","caso":"Criança de 4 anos, 16 kg, há 2 dias com diarreia com sangue e muco, febre de 39 °C, dor abdominal em cólica e tenesmo, abatida. Alerta, olhos normais, bebe normalmente, prega desaparece rápido, TEC 2 s; abdome doloroso difusamente, sem peritonite. Diurese presente.","blocos":[{"t":"Diagnóstico","q":"Qual o diagnóstico?","r":["Síndrome disentérica (diarreia aguda invasiva, provável Shigella), sem desidratação, com indicação de antibiótico."],"e":"Sangue + muco + febre + tenesmo = disenteria."},{"t":"Conduta","q":"Qual a conduta?","r":["Plano A (SRO após cada evacuação, alimentação, zinco 20 mg/dia).","Azitromicina 160 mg (10 mg/kg) no 1º dia e 80 mg/dia (5 mg/kg) por mais 4 dias (ou ceftriaxona 800 mg IM/dia por 3–5 dias).","Coprocultura se disponível; não usar antiperistáltico.","Reavaliar em 48 h; retornar se palidez, pouca urina ou manchas roxas (SHU), convulsão ou piora."],"e":"A síndrome hemolítico-urêmica é a complicação a vigiar."}]},{"id":"ce-bateria-2a","area":"Pediatria","tema":"Corpo estranho","titulo":"Criança de 2 anos sumiu com a bateria do controle","caso":"Criança de 2 anos; há 1 h a mãe achou o controle remoto aberto e a bateria sumiu. Agora baba, recusa o lanche, tosse leve. FC 130, FR 30, SatO₂ 97%, sem esforço respiratório; orofaringe normal; sem crepitação cervical. RX: imagem arredondada de 20 mm no esôfago proximal, com duplo contorno na frente e degrau no perfil.","blocos":[{"t":"Abordagem","q":"O que você pergunta e faz primeiro?","r":["ABC e via aérea primeiro.","Tipo, hora, número do objeto; bateria ou ímã? Deglute saliva?","Palpar o pescoço (enfisema); RX de frente e perfil."],"e":"Duplo contorno na frente e degrau no perfil identificam a bateria."},{"t":"Diagnóstico","q":"Qual o diagnóstico?","r":["Bateria de botão impactada no esôfago proximal: emergência.","Risco de necrose, perfuração e fístula em horas."],"e":"A corrente elétrica produz hidróxido na mucosa e lesão grave em poucas horas."},{"t":"Conduta","q":"Qual a conduta?","r":["Monitorizar; não induzir vômito; nada por boca além do protetor.","Sucralfato 10 mL a cada 10 min (até 3 doses) ou mel (≥ 1 ano, < 12 h) enquanto prepara.","Endoscopia de emergência (em menos de 2 h) sob anestesia com intubação, sem esperar o jejum.","Após a retirada: avaliar a lesão, internar, esofagograma, TC se lesão profunda, dieta pastosa.","Vigiar febre, estridor, rouquidão e hematêmese por semanas; orientar prevenção (baterias e ímãs longe das crianças)."],"e":"Mel ou sucralfato diminuem a lesão enquanto a endoscopia não chega."}]},{"id":"ce-bolo-alimentar","area":"Adulto","tema":"Corpo estranho no esôfago","titulo":"Engasgou com carne no churrasco","caso":"Homem, 38 anos, há 4 h sente a carne “parada” no peito, não consegue engolir a própria saliva (cospe), dor retroesternal. Já teve 2 episódios mais leves; disfagia intermitente para sólidos há anos; asma e rinite. Sinais vitais normais, sem enfisema subcutâneo. RX de tórax sem pneumomediastino.","blocos":[{"t":"Diagnóstico","q":"Qual o diagnóstico?","r":["Impactação de bolo alimentar no esôfago com obstrução completa (não deglute saliva).","Provável esofagite eosinofílica de base (atopia, disfagia crônica, recorrência)."],"e":"Asma e rinite + disfagia para sólidos há anos sugerem esofagite eosinofílica."},{"t":"Conduta","q":"Qual a conduta?","r":["Endoscopia emergente: empurrar o bolo com cuidado para o estômago ou retirar, com proteção de via aérea.","Biópsias esofágicas (proximal e distal, 6 fragmentos ou mais).","Não usar amaciante, bário nem forçar com alimentos; glucagon não deve atrasar.","Depois: dieta leve, IBP e, confirmada a EoE, corticoide tópico deglutido ou dieta de eliminação; seguimento com gastroenterologia."],"e":"Sem bário, sem vômito, sem “empurrar com pão”."}]},{"id":"rn-exame-normal","area":"Pediatria","tema":"Recém-nascido","titulo":"“Doutor, ele tem um galo na cabeça e pintinhas”","caso":"RN com 30 h, termo (39 semanas), AIG, parto vaginal prolongado. Mamando bem. FC 140, FR 48, T 36,8 °C. Edema mole no couro cabeludo que ultrapassa a sutura sagital; pápulas brancas no nariz; máculas eritematosas com pústulas no tronco; manchas azuladas na região sacral; hemorragia subconjuntival; mamas ingurgitadas; acrocianose. Reflexo vermelho presente e simétrico, palato íntegro, pulsos femorais normais, coto com 3 vasos, Ortolani e Barlow negativos, reflexos presentes e simétricos. Teste do coraçãozinho: 98% e 97%.","blocos":[{"t":"Como examinar","q":"Como você conduz o exame do RN?","r":["Mãos higienizadas e aquecidas; evitar hipotermia; explicar à mãe o que vai encontrar.","Sinais vitais e medidas (perímetro cefálico!) na curva.","Sequência céfalo-caudal: fontanelas, palato e clavículas, reflexo vermelho, pulsos femorais, coto com 3 vasos, ânus pérvio, Ortolani e Barlow, reflexos primitivos."],"e":"A estação cobra a sequência e a distinção entre normal e patológico."},{"t":"Achados benignos","q":"Nomeie os achados transitórios.","r":["Bossa serossanguínea (ultrapassa a sutura).","Milium (pápulas brancas no nariz).","Eritema tóxico (máculas com pústulas).","Mancha mongólica (região sacral).","Hemorragia subconjuntival.","Ingurgitamento mamário.","Acrocianose."],"e":"A bossa serossanguínea atravessa as suturas; o cefalo-hematoma não (respeita a sutura)."},{"t":"Diagnóstico e conduta","q":"Qual o diagnóstico e as orientações?","r":["RN a termo, AIG, exame físico normal, com achados transitórios benignos.","Tranquilizar e explicar que regridem sozinhos, sem tratamento.","Manter aleitamento exclusivo, cuidados com o coto, dormir de barriga para cima.","Completar triagens (pezinho no 3º–5º dia, orelhinha); consulta na 1ª semana e sinais de alerta."],"e":"Uma boa explicação à família faz parte da nota."}]},{"id":"rn-ddq","area":"Pediatria","tema":"Recém-nascido","titulo":"Ressalto no quadril","caso":"RN do sexo feminino, primogênita, apresentação pélvica, termo, 3.100 g, 36 h de vida. Exame geral normal. Pregas da coxa assimétricas. No quadril esquerdo, a abdução com elevação do trocânter produz um ressalto de redução; na adução com pressão posterior, sente-se o fêmur sair do acetábulo. Quadril direito normal.","blocos":[{"t":"Manobras","q":"Que manobras você descreve e o que sentiu?","r":["Ortolani: abdução com elevação do trocânter produz ressalto de redução.","Barlow: adução com pressão posterior sente o fêmur sair do acetábulo.","Ambos positivos no quadril esquerdo."],"e":"Ortolani reduz o quadril luxado; Barlow o luxa. Ambos positivos = quadril luxável e redutível."},{"t":"Diagnóstico","q":"Qual o diagnóstico e os fatores de risco?","r":["Displasia do desenvolvimento do quadril (DDQ) à esquerda.","Fatores de risco: sexo feminino, primogênita, apresentação pélvica."],"e":"Pregas assimétricas da coxa são sinal de apoio, não diagnóstico."},{"t":"Conduta","q":"Qual a conduta?","r":["Encaminhar logo à ortopedia pediátrica.","USG do quadril (método de Graf, idealmente com 4–6 semanas, ou antes a critério do ortopedista).","Suspensório de Pavlik (abdução e flexão) quando indicado.","Não usar fraldas duplas como tratamento.","Explicar o bom prognóstico com tratamento precoce e a importância do seguimento."],"e":"Quanto mais cedo o tratamento, melhor o resultado."}]},{"id":"rn-apgar-normal","area":"Pediatria","tema":"Recém-nascido","titulo":"RN de parto normal sem intercorrências","caso":"Mãe de 28 anos, G2P1, 8 consultas de pré-natal, sorologias negativas, estreptococo do grupo B negativo. Parto vaginal com 39+2 semanas, bolsa rota há 4 h, líquido claro. RN chora ao nascer, tônus em flexão. 1º minuto: FC > 100, choro forte, flexão ativa, chora ao estímulo, extremidades cianóticas. 5º minuto: todo róseo. Peso 3.350 g, comprimento 49 cm, PC 34 cm (AIG).","blocos":[{"t":"Apgar","q":"Some o Apgar em voz alta, sinal por sinal.","r":["1º minuto: FC > 100 (2), respiração/choro forte (2), tônus em flexão ativa (2), irritabilidade chora ao estímulo (2), cor com extremidades cianóticas (1) = 9.","5º minuto: todo róseo = 10."],"e":"Os cinco sinais são: frequência cardíaca, respiração, tônus, irritabilidade reflexa e cor. O Apgar não define a reanimação, que começa antes."},{"t":"Diagnóstico e cuidados","q":"Qual o diagnóstico e os cuidados de rotina?","r":["RN a termo, AIG, Apgar 9 e 10: boa vitalidade.","Clampeamento tardio (1–3 min), pele a pele e amamentação na 1ª hora.","Vitamina K 1 mg IM, profilaxia ocular, vacina hepatite B (e BCG), identificação, alojamento conjunto.","Exame físico completo; agendar triagens (pezinho, coraçãozinho, olhinho, orelhinha)."],"e":"Gestação a termo, respirando e com bom tônus: clampeamento tardio e pele a pele."},{"t":"Declaração de Nascido Vivo","q":"Que dados você preenche na DNV?","r":["Peso 3.350 g, Apgar 9 e 10, IG 39 semanas, 8 consultas, parto vaginal, sem anomalia.","Via amarela à família."],"e":"A DNV exige peso, Apgar, IG, consultas de pré-natal, tipo de parto e anomalias."}]},{"id":"rn-apgar-depressao","area":"Pediatria","tema":"Recém-nascido","titulo":"RN que nasce sem respirar","caso":"Mãe de 34 anos, diabetes gestacional com insulina, bolsa rota há 22 h, febre de 38,5 °C no trabalho de parto; cesárea com 37 semanas por sofrimento fetal; líquido meconial. RN sem respirar, hipotônico. 1º minuto: FC 80, apneia, flácido, sem resposta, pálido → passos iniciais + VPP. 5º minuto: FC 140, respiração irregular, alguma flexão, careta, extremidades cianóticas. 10º minuto: 8. Peso 4.250 g (GIG).","blocos":[{"t":"Diagnóstico","q":"Qual o diagnóstico e os riscos?","r":["RN a termo, GIG, filho de mãe diabética.","Depressão neonatal grave no 1º min (Apgar 1 / 6 / 8).","Risco de sepse precoce (bolsa rota > 18 h + febre materna)."],"e":"Bolsa rota prolongada com febre materna é fator de risco para sepse precoce."},{"t":"Conduta","q":"Qual a conduta imediata e na UTI?","r":["Clampeamento imediato, passos iniciais, VPP em ar ambiente no minuto de ouro, monitor e oximetria.","UTI neonatal: glicemia capilar precoce e seriada (hipoglicemia), gasometria do cordão.","Avaliar encefalopatia hipóxico-isquêmica (hipotermia terapêutica se critérios, em até 6 h).","Hemocultura, hemograma, PCR e ampicilina + gentamicina; vitamina K e hepatite B."],"e":"Filho de mãe diabética tem risco de hipoglicemia pelo hiperinsulinismo."},{"t":"DNV e família","q":"O que registrar e comunicar?","r":["DNV: peso 4.250 g, Apgar 1 e 6, cesárea, sem anomalia.","Comunicar a família."],"e":"A DNV registra o Apgar do 1º e 5º minuto, mesmo quando houve depressão."}]},{"id":"drge-tipica","area":"Adulto","tema":"DRGE e dispepsia","titulo":"DRGE típica sem sinais de alarme","caso":"Mulher, 34 anos, pirose e regurgitação ácida 3 vezes por semana há 4 meses, piores após o jantar e ao deitar. Sem disfagia ou perda de peso. IMC 28. Exame normal.","blocos":[{"t":"Anamnese","q":"O que você pergunta?","r":["Se a queimação sobe do estômago para o peito e se piora ao deitar.","Dificuldade para engolir (alarme), perda de peso.","Excluir causa cardíaca; medicações que pioram; IMC."],"e":"Disfagia, perda de peso, sangramento e anemia são sinais de alarme que indicam EDA."},{"t":"Diagnóstico","q":"Qual o diagnóstico e a indicação de EDA?","r":["DRGE típica (diagnóstico clínico), sem sinais de alarme.","Sem indicação de EDA agora."],"e":"Na DRGE típica sem alarme, o diagnóstico é clínico e o tratamento é empírico."},{"t":"Conduta","q":"Qual o tratamento?","r":["Estilo de vida: perder peso, jantar 3 h ou mais antes de deitar, elevar a cabeceira.","Omeprazol 20 mg 1 vez ao dia, 30–60 min antes do café, por 8 semanas.","Retorno em 8 semanas: melhorou → desmame (menor dose ou sob demanda); falhou ou recidivou → EDA.","Voltar antes se disfagia, sangramento ou perda de peso."],"e":"O IBP deve ser tomado antes da primeira refeição para ter eficácia."}]},{"id":"drge-complicada","area":"Adulto","tema":"DRGE e dispepsia","titulo":"DRGE com disfagia e perda de peso","caso":"Homem, 58 anos, branco, tabagista, IMC 33, pirose há 15 anos. Há 3 meses, disfagia progressiva para sólidos e perda de 4 kg. EDA: estenose péptica distal, esofagite LA C, epitélio colunar de 4 cm; biópsia: metaplasia intestinal com displasia de baixo grau (confirmada por 2º patologista), sem neoplasia.","blocos":[{"t":"Diagnóstico","q":"Qual o diagnóstico?","r":["DRGE complicada: esofagite erosiva LA C + estenose péptica + esôfago de Barrett longo com displasia de baixo grau."],"e":"Fatores de risco do Barrett: homem, branco, mais de 50 anos, obesidade abdominal, tabagismo e DRGE longa."},{"t":"Conduta","q":"Qual a conduta?","r":["IBP em dose dobrada, contínuo.","Dilatação endoscópica da estenose.","Parar de fumar e perder peso.","Barrett com displasia → terapia endoscópica de erradicação (ressecção + ablação por radiofrequência) e vigilância.","Considerar fundoplicatura após manometria e pHmetria."],"e":"Antes de qualquer cirurgia antirrefluxo, a manometria exclui distúrbio motor."}]},{"id":"do-natural","area":"Adulto","tema":"Declaração de óbito","titulo":"Óbito hospitalar por doença","caso":"Homem, 68 anos, diabético e hipertenso há 20 anos, internado há 3 dias com infarto agudo do miocárdio de parede anterior. Evoluiu com choque cardiogênico há 12 h, sem resposta a drogas vasoativas, e teve parada cardiorrespiratória não revertida. Você é o médico assistente de plantão e constatou o óbito às 03h40.","blocos":[{"t":"Quem emite","q":"Você emite a DO? Por quê?","r":["Morte natural com assistência médica, causa conhecida: o médico assistente emite.","Sem necessidade de SVO nem IML."],"e":"Constatar o óbito vem antes de preencher a DO. Morte natural com causa definida: assistente; sem causa definida: SVO; causa externa: IML."},{"t":"Parte I e II","q":"Como você preenche as causas?","r":["Parte I: a) choque cardiogênico (12 h); b) infarto agudo do miocárdio de parede anterior (3 dias).","Parte II: diabetes mellitus tipo 2 (20 anos); hipertensão arterial (20 anos).","Causa básica na última linha; não escrever “parada cardiorrespiratória”."],"e":"A cadeia causal é lida de baixo para cima: a causa básica é a última linha da Parte I."},{"t":"Finalização","q":"O que mais faz parte?","r":["CID em branco; preencher todos os blocos, CRM e assinatura; letra legível, sem siglas.","Via amarela à família; branca e rosa ficam no serviço.","Comunicar a família com acolhimento."],"e":"Mulher em idade fértil: preencher o campo de gestação."}]},{"id":"do-externa","area":"Adulto","tema":"Declaração de óbito","titulo":"Óbito após atropelamento","caso":"Mulher, 35 anos, atropelada por carro ao atravessar a avenida; chegou ao pronto-socorro com traumatismo cranioencefálico grave, foi operada e morreu 2 dias depois na UTI. A família pede que você, que acompanhou a internação, “faça logo o atestado” para o velório.","blocos":[{"t":"Decisão","q":"Você emite a DO?","r":["Não. Morte por causa externa (acidente de transporte: pedestre atropelado) não é morte natural, mesmo após internação.","Emitir seria infração ética."],"e":"Qualquer morte por causa externa (acidente, homicídio, suicídio) é de competência do IML, mesmo que haja dias de internação."},{"t":"Conduta","q":"O que você faz, então?","r":["Registrar tudo no prontuário.","Comunicar a autoridade policial e encaminhar o corpo ao IML, que emitirá a DO (a: TCE grave; b: pedestre atropelado por automóvel em via pública; bloco VII: acidente, fonte: boletim de ocorrência).","Explicar à família, com empatia, por que o IML é obrigatório e os próximos passos."],"e":"A pressa do velório não muda a obrigação. A empatia muda a forma de explicar."}]},{"id":"gest-pelvica","area":"Adulto","tema":"Gestação e ginecologia","titulo":"Leopold “diferente” no fim da gestação","caso":"G2P1, 36 semanas, pré-natal sem intercorrências, queixa de “dor nas costelas”. PA 110/70; AU 35 cm. 1ª manobra: polo duro, arredondado e rechaçável no fundo. 2ª: dorso à direita. 3ª: polo inferior volumoso, irregular, amolecido, não insinuado. BCF 144 bpm acima da cicatriz umbilical, à direita.","blocos":[{"t":"Preparo e exame","q":"Como você prepara e examina?","r":["Mãos aquecidas e higienizadas; bexiga vazia; evitar hipotensão supina.","PA com técnica correta; fita na borda superior da sínfise e fundo delimitado.","4 manobras de Leopold na ordem; BCF por 1 minuto com pulso materno."],"e":"A bexiga vazia evita desconforto e erro na altura uterina."},{"t":"Diagnóstico","q":"Descreva a situação do feto.","r":["Gestação de 36 semanas, situação longitudinal, apresentação pélvica, dorso à direita, não insinuado, BCF normal."],"e":"Polo duro, arredondado e rechaçável no fundo (cabeça); polo inferior volumoso e irregular (nádegas)."},{"t":"Conduta","q":"Qual a conduta?","r":["USG para confirmar a apresentação e avaliar placenta, líquido e malformações.","Oferecer versão cefálica externa (cerca de 36–37 semanas, em hospital, com tocólise e monitorização), se não houver contraindicação (placenta prévia, oligodrâmnio, sangramento, cesárea anterior conforme serviço).","Se persistir pélvica: discutir via de parto (cesárea eletiva com 39 semanas ou mais).","Orientar sinais de trabalho de parto e retorno semanal."],"e":"Sem sangramento, a USG antes de tocar a placenta evita risco."}]},{"id":"gest-preeclampsia","area":"Adulto","tema":"Gestação e ginecologia","titulo":"Cefaleia e escotomas com 34 semanas","caso":"Primigesta, 34 semanas, cefaleia intensa e escotomas há 6 h, dor epigástrica. PA 164/112 (repetida após 15 min: 166/110). Ganho de 2 kg em 1 semana, edema de face e mãos, reflexos patelares vivos. AU 30 cm, BCF 140 bpm, útero relaxado. Proteína/creatinina 0,9; plaquetas 140 mil; TGO 38; creatinina 0,8.","blocos":[{"t":"Diagnóstico","q":"Qual o diagnóstico?","r":["Pré-eclâmpsia com sinais de gravidade: hipertensão grave + sintomas neurológicos (iminência de eclâmpsia)."],"e":"Cefaleia, escotomas, dor epigástrica e hiper-reflexia são pródromos da eclâmpsia."},{"t":"Medidas iniciais","q":"O que você faz agora?","r":["Internar, decúbito lateral esquerdo, 2 acessos, sonda vesical (diurese).","Sulfato de magnésio: ataque 4 g IV em 10–20 min + manutenção 1–2 g/h por 24 h (Zuspan).","Vigiar reflexos, FR acima de 10–12 e diurese acima de 25–30 mL/h; antídoto: gluconato de cálcio 1 g IV."],"e":"O sulfato de magnésio previne convulsão. Perda do reflexo patelar é o primeiro sinal de intoxicação."},{"t":"Pressão e desfecho","q":"Como tratar a PA e qual o desfecho?","r":["Nifedipino 10 mg VO (repetir a cada 20–30 min) ou hidralazina 5 mg IV até PAD 90–100.","Laboratório para HELLP; avaliar o feto (cardiotocografia, USG/Doppler); corticoide conforme protocolo.","Com 34 semanas ou mais e gravidade: interromper a gestação após estabilizar (via obstétrica)."],"e":"O tratamento definitivo da pré-eclâmpsia é o parto."}]},{"id":"abuso-crianca","area":"Pediatria","tema":"Violência sexual e adolescência","titulo":"Corrimento em menina de 5 anos","caso":"Lia, 5 anos, trazida pela mãe por corrimento amarelado há 10 dias e ardor ao urinar. A mãe notou que voltou a fazer xixi na cama, tem pesadelos e passou a chorar quando vai à casa de um parente. Exame (com consentimento e a mãe presente, em posição de rã): vulva hiperemiada, corrimento purulento, sem lacerações visíveis. Pesquisa de gonococo positiva (PCR) no corrimento.","blocos":[{"t":"Diagnóstico","q":"Qual o diagnóstico e o que sustenta?","r":["Abuso sexual: gonorreia em criança fora do período perinatal é marcador diagnóstico.","Alterações comportamentais.","Exame genital sem lesão aguda (frequente): exame normal não exclui."],"e":"IST em criança pré-púbere, fora do período neonatal, deve levantar a suspeita de violência sexual."},{"t":"Acolhimento","q":"Como você conduz o atendimento?","r":["Acolher a criança e a mãe, sem interrogatório repetido; registrar as falas literais.","Exame com consentimento, acompanhante, posição de rã e sem espéculo.","Não prometer segredo."],"e":"Escuta sem induzir: a escuta especializada é feita por profissional treinado."},{"t":"Conduta","q":"Qual a conduta?","r":["Tratar a gonorreia (ceftriaxona IM por peso); testar clamídia, sífilis, HIV e hepatites.","Notificação compulsória e comunicação ao Conselho Tutelar.","Avaliar a segurança: afastar o contato com o suspeito; internar se não houver proteção.","Escuta especializada e psicologia; sem PEP (exposição há mais de 72 h); seguimento sorológico."],"e":"A segurança da criança é verificada antes da alta."}]},{"id":"violencia-adolescente","area":"Pediatria","tema":"Violência sexual e adolescência","titulo":"Adolescente após violência sexual","caso":"Carla, 15 anos, chega ao pronto-socorro com uma amiga 10 horas após ter sido violentada por um desconhecido em uma festa. Não tomou banho. Chorosa, com medo de contar aos pais. Equimoses em coxas internas; laceração recente na fúrcula posterior. DUM há 12 dias; não usa contracepção. Vacinação para hepatite B incompleta.","blocos":[{"t":"Acolhimento","q":"Como você recebe a paciente?","r":["Acolhimento e atendimento imediato, sem exigir boletim de ocorrência.","Frase de apoio: “você fez muito bem em me contar; o que aconteceu não é culpa sua”.","Não prometer segredo; explicar antes a ela o que será comunicado."],"e":"O atendimento não depende de BO."},{"t":"Profilaxias","q":"Quais as profilaxias, e por que agora?","r":["Dentro de 72 h: PEP para HIV (28 dias).","Profilaxia de IST: ceftriaxona + azitromicina + metronidazol.","Vacina da hepatite B ± imunoglobulina.","Contracepção de emergência: levonorgestrel 1,5 mg.","Testes basais: HIV, sífilis, hepatites, β-hCG."],"e":"A janela da PEP é de até 72 h; quanto antes, melhor."},{"t":"Notificação e seguimento","q":"O que mais?","r":["Coleta de vestígios com consentimento (IML/cadeia de custódia).","Notificação e Conselho Tutelar (explicando a ela antes); apoiar a conversa com a família.","Psicologia; seguimento em 30 dias, 3 e 6 meses."],"e":"A notificação é compulsória, inclusive em adolescentes."}]},{"id":"adol-sigilo","area":"Pediatria","tema":"Violência sexual e adolescência","titulo":"“Doutora, minha mãe não pode saber”","caso":"Ana, 16 anos, vem sozinha à UBS. Namora há 6 meses um rapaz de 17 anos; relações sexuais consensuais, usam preservativo “às vezes”. Quer um método para não engravidar e pede que a mãe não saiba. Nega violência, coerção, drogas ou tristeza; vai bem na escola. DUM há 12 dias. Exame normal; teste rápido de gravidez negativo.","blocos":[{"t":"Sigilo","q":"Como você trata o pedido de sigilo?","r":["Apresentar-se à adolescente (e ao responsável, se presente); consulta em dois momentos.","Explicar o sigilo e seus limites: risco à vida ou alguém a machucando.","Atender e manter o sigilo (CEM art. 74)."],"e":"Roteiro: “o que você me contar fica entre nós, exceto se houver risco à sua vida ou se alguém estiver te machucando; nesse caso, eu te conto antes”."},{"t":"Diagnóstico","q":"Qual a avaliação?","r":["Adolescente com vida sexual ativa consensual, com capacidade de discernimento, em risco de gravidez não planejada e de IST.","Sem situação que justifique quebra de sigilo."],"e":"Perguntar sempre sobre consentimento e idade do parceiro (HEADSSS sem julgamento)."},{"t":"Conduta","q":"O que você oferece?","r":["Aconselhar e oferecer LARC (implante ou DIU) ou outro método da escolha dela, sempre com preservativo (dupla proteção).","Orientar contracepção de emergência.","Testes rápidos (HIV, sífilis, hepatites); vacina HPV e hepatite B em dia.","Estimular, sem impor, o diálogo com a família; registrar no prontuário e agendar retorno."],"e":"A contracepção não depende da autorização dos pais."}]},{"id":"adol-vulneravel","area":"Pediatria","tema":"Violência sexual e adolescência","titulo":"Atraso menstrual aos 13 anos","caso":"Júlia, 13 anos, trazida pela tia por dor abdominal. A sós, conta atraso menstrual de 2 meses; teve relações com o “namorado” de 19 anos, vizinho, que pediu segredo; diz que foi porque quis. Está com medo e chora. Útero aumentado; teste de gravidez positivo, cerca de 10 semanas pela DUM.","blocos":[{"t":"Diagnóstico","q":"Qual o diagnóstico e o enquadramento legal?","r":["Gravidez na adolescência (cerca de 10 semanas).","Estupro de vulnerável: menor de 14 anos, o consentimento não tem validade legal.","Situação de violência sexual que justifica a quebra do sigilo."],"e":"Em menor de 14 anos, a relação sexual é violência sexual, mesmo que “consentida”."},{"t":"Conduta","q":"Como você procede?","r":["Acolher sem julgamento e explicar a ela, antes, por que outras pessoas precisarão saber, para protegê-la.","Notificação compulsória de violência sexual (SINAN) e comunicação ao Conselho Tutelar; acionar serviço social e psicologia.","Avaliar a segurança (o agressor é vizinho)."],"e":"Quebrar o sigilo aqui é uma obrigação legal e protege a paciente."},{"t":"Opções","q":"Que opções são apresentadas?","r":["Informar, com o responsável legal, o direito ao aborto legal (sem necessidade de BO) e as opções, respeitando a vontade dela.","Se seguir a gestação: pré-natal de alto risco, exames, testes de IST, ácido fólico e ferro, apoio escolar e psicológico."],"e":"Gestação por violência sexual é situação de aborto legal."}]},{"id":"tanner-turner","area":"Pediatria","tema":"Puberdade e amenorreia","titulo":"“Ela não menstruou e não cresce”","caso":"Mariana, 15 anos, nunca menstruou. Altura 140 cm (< p3), alvo genético 160 cm; pescoço alado, tórax em escudo com mamilos afastados, cúbito valgo, múltiplos nevos. Tanner M1 P2. Genitália externa feminina normal. β-hCG negativo. FSH 85 e LH 30 mUI/mL (altos), estradiol baixo; USG: útero infantil, ovários não visualizados.","blocos":[{"t":"Exame","q":"Como você examina e classifica?","r":["Consentimento e acompanhante; exposição respeitosa.","Altura na curva e estigmas; Tanner de mamas e de pelos classificados separadamente.","Genitália na posição de rã, tração dos lábios, sem espéculo."],"e":"Amenorreia primária = ausência de menarca aos 15 anos, ou aos 13 sem caracteres sexuais secundários."},{"t":"Diagnóstico","q":"Qual o diagnóstico?","r":["Amenorreia primária com atraso puberal por hipogonadismo hipergonadotrófico: síndrome de Turner provável."],"e":"FSH e LH altos com estradiol baixo mostram falência ovariana. Primeiro β-hCG; depois: tem mamas? tem útero? FSH?"},{"t":"Conduta","q":"Qual a conduta?","r":["Cariótipo (45,X/mosaico; se houver material Y, gonadectomia).","Rastrear: ecocardiograma (coarctação), USG renal, TSH, audiometria, PA.","Endocrinologia pediátrica: GH (se houver potencial de crescimento) e indução puberal com estrogênio em dose baixa progressiva, depois associar progestagênio.","Apoio psicológico; conversar sobre fertilidade no futuro (ovodoação)."],"e":"O rastreio de malformações associadas é parte do seguimento."}]},{"id":"himen-imperfurado","area":"Pediatria","tema":"Puberdade e amenorreia","titulo":"Dor todo mês, mas sem menstruação","caso":"Beatriz, 14 anos, nunca menstruou, mas há 4 meses tem dor em baixo ventre todo mês, por 3–4 dias; agora com dificuldade para urinar. Altura e peso normais, Tanner M4 P4; massa suprapúbica dolorosa. Inspeção da vulva (com consentimento e acompanhante): membrana himenal abaulada, azulada, sem orifício. β-hCG negativo. USG: hematocolpo volumoso, útero normal.","blocos":[{"t":"Diagnóstico","q":"Qual o diagnóstico?","r":["Amenorreia primária por obstrução do trato genital: hímen imperfurado com hematocolpo.","Puberdade normal, útero presente."],"e":"Dor cíclica sem menstruação, com caracteres sexuais normais, aponta para obstrução."},{"t":"Conduta","q":"Qual a conduta?","r":["Analgesia; esvaziar a bexiga se retenção (sonda).","Encaminhar à ginecologia infantopuberal/cirurgia para himenotomia (incisão em cruz ou elíptica e drenagem do sangue retido).","Explicar à paciente e à família que a função reprodutiva é normal; retorno pós-operatório."],"e":"O tratamento é cirúrgico simples e o prognóstico é excelente."}]},{"id":"parasitose-crianca","area":"Pediatria","tema":"Parasitoses","titulo":"Criança pálida da zona rural","caso":"Menino de 7 anos, zona rural, descalço, sem esgoto, água de poço. Cansaço, come terra, dor abdominal, eliminou “lombriga”. Palidez +++, sopro sistólico leve, peso no P3. Hemograma: Hb 7,6, VCM 64, HCM 19, RDW 19%, eosinófilos 15% (1.350/mm³); ferritina 4. EPF (Hoffman): ovos de ancilostomídeo e de Ascaris.","blocos":[{"t":"Anamnese e hemograma","q":"O que você pergunta e como lê o hemograma?","r":["Anamnese epidemiológica: água tratada, esgoto, anda descalço, coceira anal à noite.","Peso na curva.","Anemia microcítica e hipocrômica (ferropriva) com eosinofilia."],"e":"O EPF deve ser pedido com 3 amostras e método adequado (Hoffman)."},{"t":"Diagnóstico","q":"Qual o diagnóstico?","r":["Ancilostomíase + ascaridíase, com anemia ferropriva, eosinofilia leve e desnutrição."],"e":"O ancilostomídeo suga sangue e causa anemia ferropriva."},{"t":"Conduta","q":"Qual o tratamento e a prevenção?","r":["Albendazol 400 mg em dose única (trata os dois; criança com 2 anos ou mais).","Sulfato ferroso 3–5 mg/kg/dia de ferro elementar, longe do leite, até cerca de 3 meses após a Hb normalizar.","Hemograma em cerca de 4 semanas; EPF de controle; avaliação nutricional.","Prevenção: calçados, lavar as mãos, água fervida/filtrada, examinar a família."],"e":"No oxiúro, repetir a dose em 2 semanas e tratar a família."}]},{"id":"strongyloides","area":"Adulto","tema":"Parasitoses","titulo":"Imunossuprimido grave com larvas nas fezes","caso":"Homem, 58 anos, veio da zona rural da Bahia, em prednisona 40 mg/dia há 3 semanas (DPOC). Agora: febre, dispneia, dor abdominal, diarreia e púrpura periumbilical. PA 85/50, hemocultura com E. coli, infiltrado pulmonar bilateral. Eosinófilos normais. Larvas de Strongyloides no escarro e nas fezes.","blocos":[{"t":"Diagnóstico","q":"Qual o diagnóstico?","r":["Síndrome de hiperinfecção / estrongiloidíase disseminada desencadeada por corticoide.","Sepse por gram-negativo.","Sem eosinofilia pelo efeito do corticoide."],"e":"Corticoide derruba os eosinófilos e favorece a hiperinfecção."},{"t":"Conduta","q":"Qual a conduta?","r":["UTI: volume, antibiótico amplo para gram-negativo.","Ivermectina 200 µg/kg/dia até exames negativos por 2 semanas ou mais.","Reduzir o corticoide; pesquisar HTLV-1 e HIV."],"e":"Lição: rastrear e tratar Strongyloides antes de iniciar corticoide em quem vem de área endêmica."}]}]};
